(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c43"]=[{"id":"00000519","register_sub_id":"101","register_pk":"101509","name":"細井家住宅文庫蔵","kana":"ほそいけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町静川字風下甲175","lat":37.19783011,"lng":139.68524785,"geo_status":"db","era":"文政年間","year":1824,"year_source":"estimated","year_min":1818,"year_max":1830,"year_label":"文政年間","structure":"土蔵造２階建，鉄板葺，建築面積54㎡","structure_material":"土蔵造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"07 － 0017","desc":"主屋の後方西寄りに建つ。置屋根形式の２階建土蔵で，腰に下見板を張る。小規模ながら棟通りに柱を立てる点が珍しい。内部壁面を羽目板とすることから，当初から貴重品を入れる蔵として建てられたことがわかる。大規模農家の屋敷構えの貴重な構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000519"},{"id":"00000522","register_sub_id":"101","register_pk":"101512","name":"細井家住宅門","kana":"ほそいけじゅうたくもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町静川字風下甲175","lat":37.19771234,"lng":139.68541394,"geo_status":"db","era":"万延2","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造，鉄板葺","structure_material":"木造","registered":"1998.04.21(平成10.04.21)","register_no":"07 － 0020","desc":"郵便局舎の西に隣接して道に面して建つ棟門。主屋と同時期の建築で，村名主を勤めた家柄をあらわす建物で，大規模農家の屋敷構えの貴重な構成要素である。道路との間にある門に附属する石橋は，絵図によって万延２年より前からあったことが知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000522"},{"id":"00001478","register_sub_id":"101","register_pk":"102468","name":"堀金家住宅（臣の郷）隠居所","kana":"ほりがねけじゅうたく（おみのさと）いんきょじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県南会津郡南会津町静川字風下甲171","lat":37.19750193,"lng":139.68464802,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、茅葺、建築面積96㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"07 － 0035","desc":"敷地西側，主屋と対になる位置に建ち，建築年代は明治中期頃と伝えられている。２階建，寄棟造・茅葺で，南北棟とし，東面と南面を開口部とする。外観は民家と同様であるが，内部は床・棚を構えた座敷を備えるなど，近代の数寄屋風意匠となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001478"},{"id":"00001477","register_sub_id":"101","register_pk":"102467","name":"堀金家住宅（臣の郷）水車小屋","kana":"ほりがねけじゅうたく（おみのさと）すいしゃごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町静川字風下甲171","lat":37.19745121,"lng":139.68472164,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2000.02.15(平成12.02.15)","register_no":"07 － 0034","desc":"堀金家の屋敷は旧道に面しており，もとは道路際に水路が流れていた。土蔵の南側にある水車小屋は，切妻造・もと木羽葺の簡素な建物で，現在は物置として使われている。棟が旧道と直交しており，旧道側の妻面に，昭和２０年代まで水車が設けられていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001477"},{"id":"00001476","register_sub_id":"101","register_pk":"102466","name":"堀金家住宅（臣の郷）土蔵","kana":"ほりがねけじゅうたく（おみのさと）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町静川字風下甲171","lat":37.19756138,"lng":139.68467571,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、鉄板葺、建築面積73㎡","structure_material":"土蔵造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"07 － 0033","desc":"ほぼ南面して建つ主屋北西に建ち，主屋と同時期の建築と伝えられている。内部は２階を体験学習のための宿泊に用いている。切妻造・妻入，置屋根式鉄板葺，外壁白漆喰塗は当地域の標準的な土蔵形式であるが，小規模ながら丁寧な仕事でつくられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001476"},{"id":"00014318","register_sub_id":"101","register_pk":"511307","name":"松田家住宅表門及び板塀","kana":"まつだけじゅうたくおもてもんおよびいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県伊達郡国見町大字貝田字町裏3","lat":37.903575,"lng":140.57697222,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"表門：木造、瓦葺、間口2.5m、袖塀付 板塀：木造、鉄板葺、総延長20m","structure_material":"表門：木造","registered":"2022.10.31(令和4.10.31)","register_no":"07 - 0276","desc":"奥州街道に北面して建つ表門。切妻造間口一間の門で桟瓦葺、柱に渡した冠木上に梁を架け、束で母屋、棟木を受け、明快な造りとする。板塀は半間毎に柱を立て、軒は腕木で支持する。表門の東に板塀が長く続いて敷地の表構えを整え、街道の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014318"},{"id":"00014316","register_sub_id":"101","register_pk":"511305","name":"松田家住宅主屋","kana":"まつだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県伊達郡国見町大字貝田字町裏3","lat":37.90354167,"lng":140.57709722,"geo_status":"db","era":"明治43年／昭和25年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積139㎡","structure_material":"木造平屋一部2階建","registered":"2022.10.31(令和4.10.31)","register_no":"07 - 0274","desc":"奥州街道の貝田宿に所在する養蚕農家。平屋建一部二階で北を入母屋造、南を切妻造とし、棟に煙出を設ける。内部は南に土間、北に六室で天井高く張り、縁を二層とする。外壁は軒裏を漆喰塗込、雨戸や戸袋を鉄板張とし、厳重に防火に備え、独特な外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014316"},{"id":"00014317","register_sub_id":"101","register_pk":"511306","name":"松田家住宅土蔵","kana":"まつだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県伊達郡国見町大字貝田字町裏3","lat":37.90347222,"lng":140.57726389,"geo_status":"db","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"07 - 0275","desc":"主屋の東に位置し、家財を収納する土蔵。二階建切妻造平入桟瓦葺の南北棟で、西面に戸口を設けて下屋を付す。外壁は中塗仕上で軒廻りは漆喰仕上、南面腰は海鼠壁とする。内部各階は一室の板敷で、二階の棚は建具を鉄板で被覆し、内部も防火を意識した土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014317"},{"id":"00000941","register_sub_id":"101","register_pk":"101931","name":"松本家住宅茶室","kana":"まつもとけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"福島県","address":"福島県いわき市中之作字榎戸31-1","lat":36.96139722,"lng":140.94654722,"geo_status":"db","era":"昭和20","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積53㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"07 － 0026","desc":"屋敷地の北東にあり，書院構えのある８畳大の座敷，１間半の床や炉付きの６畳大の茶室および３畳大の水屋からなる切妻造の建物。南妻に「一太郎庵」と書いた掲額がある。簡素な佇まいながら，上質な造りとなる建屋で，茶室を持つ離れの好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000941"},{"id":"00000942","register_sub_id":"101","register_pk":"101932","name":"松本家住宅離れ","kana":"まつもとけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"福島県","address":"福島県いわき市中之作字榎戸31-1","lat":36.96134167,"lng":140.94671667,"geo_status":"db","era":"昭和20","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積39㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"07 － 0027","desc":"茶室の西側に接続して建つ寄棟造の建物。１０畳大の洋室の周囲に縁及び廊下が付く。当初から書棚と出窓を備え，書斎として造られたもの。天保６年から酒造業を営む旧家の生活文化の一端を知る上で貴重な遺構で，東京八王子の大工棟梁大塚桃太郎が手がけた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000942"},{"id":"00010417","register_sub_id":"101","register_pk":"202447","name":"矢吹家住宅表門","kana":"やぶきけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県福島市成川字上谷地35","lat":37.737643,"lng":140.425693,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造、瓦葺、間口3.3m、左右袖塀付","structure_material":"木造","registered":"2015.03.26(平成27.03.26)","register_no":"07 － 0158","desc":"敷地東面南寄りに構える、総ケヤキ造の薬医門で、間口三・三メートル、切妻造桟瓦葺とし、左右に袖塀を付ける。冠木上の女梁に渦紋を飾り、男梁の両端で桁を受ける。門口に開く板扉や袖塀の壁板もケヤキの一枚板をはめる。旧家の表構えに風格を与える重厚な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010417"},{"id":"00010412","register_sub_id":"101","register_pk":"202443","name":"矢吹家住宅座敷蔵及び仏間","kana":"やぶきけじゅうたくざしきぐらおよびぶつま","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"福島県","address":"福島県福島市成川字上谷地35","lat":37.737933,"lng":140.425027,"geo_status":"db","era":"座敷蔵 明治中期 仏間 昭和初期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階一部平屋建、瓦葺及び鉄板葺、建築面積97㎡","structure_material":"土蔵造2階一部平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"07 － 0153","desc":"主屋北西側に位置し、土蔵造二階建の座敷蔵に平屋の仏間を附属する。座敷蔵下階に座敷二室を配し、北室に洗練された意匠の座敷飾を備える。仏間は仏堂風の須弥壇を構え、折上格天井、火灯窓を造作し、軒を扇垂木とするなど住宅の仏間として破格な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010412"},{"id":"00010409","register_sub_id":"101","register_pk":"202440","name":"矢吹家住宅主屋","kana":"やぶきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県福島市成川字上谷地35","lat":37.737784,"lng":140.425345,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、茅葺（鉄板仮葺）、建築面積357㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"07 － 0150","desc":"敷地中ほどに南面する、桁行二四メートルを測る住宅。四列並べた居室の土間寄りの列に客用玄関を構え、二列目を大広間とし、西端列を上質な座敷として縁を廻らす。土間側の屋根を切上げて当地でアズマヅクリと呼ぶ形式とするなど、県北の民家の発展形態を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010409"},{"id":"00010413","register_sub_id":"101","register_pk":"202444","name":"矢吹家住宅新蔵","kana":"やぶきけじゅうたくしんくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県福島市成川字上谷地35","lat":37.737515,"lng":140.42565,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積94㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"07 － 0154","desc":"敷地南東隅に東西棟で建つ。土蔵造二階建、切妻造桟瓦葺で、北西面に戸口を設けて下屋を付す。外壁は腰を海鼠壁とし、屋根は置屋根式として鉢巻を廻らし、軒先まで塗込める。各面に窓を配して掛子塗戸を開く。旧家の屋敷構えを象徴する豪壮な土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010413"},{"id":"00010410","register_sub_id":"101","register_pk":"202441","name":"矢吹家住宅新座敷","kana":"やぶきけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県福島市成川字上谷地35","lat":37.737872,"lng":140.425224,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺及び鉄板葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"07 － 0151","desc":"主屋背面に接続して東西棟で建ち、寄棟造桟瓦葺とし、下屋を廻らす。八畳二室を並べて三方に縁を廻らし、西のキャクマが主室で床と違棚を備え、東のヒカエとの室境に透彫欄間を飾る。雨戸を主屋側に引込んで開放し、後庭との一体感が図られた座敷棟である","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010410"},{"id":"00010416","register_sub_id":"101","register_pk":"202446","name":"矢吹家住宅外便所","kana":"やぶきけじゅうたくそとべんじょ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県福島市成川字上谷地35","lat":37.737769,"lng":140.425598,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造平屋建、瓦葺、建築面積19㎡","structure_material":"土蔵造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"07 － 0157","desc":"主屋土間部の東方、味噌蔵の西側に軒を接して東西棟で建つ。木造平屋建、切妻造桟瓦葺で北面に下屋を設ける。南半を三室の便房として西面に円窓を穿ち、北半は物置とする。外壁は真壁漆喰塗で腰板壁を張る。使用人用の施設とみられ、往時の生活様態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010416"},{"id":"00010415","register_sub_id":"101","register_pk":"202521","name":"矢吹家住宅道具蔵及び木小屋","kana":"やぶきけじゅうたくどうぐぐらおよびきごや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県福島市成川字上谷地35","lat":37.737922,"lng":140.425657,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造平屋建、瓦葺、建築面積42㎡","structure_material":"土蔵造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"07 － 0156","desc":"敷地東辺の北寄りに建ち、南半を土蔵造平屋建の道具蔵とし、北半を平屋建の板の間と木小屋とする。通り側の外観は一連の長い土蔵に見せ、腰を海鼠壁とし鉢巻を廻らせる。西側は戸口を設けて下屋を通す。味噌蔵や新蔵等と共に集落内の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010415"},{"id":"00010418","register_sub_id":"101","register_pk":"202448","name":"矢吹家住宅庭門及び内塀","kana":"やぶきけじゅうたくにわもんおよびうちべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県福島市成川字上谷地35","lat":37.73801604,"lng":140.42536976,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"庭門 木造、鉄板葺、間口1.6m 内塀 木造、鉄板葺、総延長28m","structure_material":"庭門 木造","registered":"2015.03.26(平成27.03.26)","register_no":"07 － 0159","desc":"新蔵北西隅から主屋方向に折曲がりに延びて前庭と主庭を画す塀と、主屋後方で中庭と後庭を画す庭門及び塀からなる。庭門は切妻造の腕木門で軸部から軒に至るまで丸太で構成する。塀は外側を板張、内側を杉皮張とする。庭空間に格式と彩りを添える門塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010418"},{"id":"00010411","register_sub_id":"101","register_pk":"202442","name":"矢吹家住宅文庫蔵","kana":"やぶきけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県福島市成川字上谷地35","lat":37.737776,"lng":140.425115,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"07 － 0152","desc":"主屋西側に南北棟で建ち、土蔵造二階建、切妻造桟瓦葺である。西面は腰を布石積として上部を海鼠壁とし、他は海鼠壁と黒漆喰仕上とする。北妻の戸口は主屋からの廊下側に扉を開き、二階に和室を配して南間に棹縁天井を張る。屋敷構えを引立てる重厚な趣の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010411"},{"id":"00010414","register_sub_id":"101","register_pk":"202445","name":"矢吹家住宅味噌蔵","kana":"やぶきけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県福島市成川字上谷地35","lat":37.737757,"lng":140.425674,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階一部平屋建、瓦葺、建築面積94㎡、門付","structure_material":"土蔵造2階一部平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"07 － 0155","desc":"敷地の東辺中央、表門と道具蔵の間に建つ。土蔵造二階建の味噌蔵の南側に、平屋建の座敷部を附属する。北端は、道具蔵との間に小門を開く。通り沿いは味噌蔵や座敷部と一連の海鼠壁を表し、味噌蔵の上下階に窓を並べ掛子塗戸を開く。街路景観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010414"},{"id":"00010419","register_sub_id":"101","register_pk":"202449","name":"矢吹家住宅南門及び外塀","kana":"やぶきけじゅうたくみなみもんおよびそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県福島市成川字上谷地35","lat":37.73747556,"lng":140.42538314,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"南門 木造、瓦葺、間口2.7m、左右袖塀付 外塀 木造、瓦葺及び鉄板葺、総延長40m","structure_material":"南門 木造","registered":"2015.03.26(平成27.03.26)","register_no":"07 － 0160","desc":"新蔵南西隅から西にのびて敷地南辺を画し、新蔵寄りに南門を開く。南門は腕木門形式で切妻造桟瓦葺として袖塀を斜に付ける。外塀は表側の腰を簓子下見板張として小壁を漆喰で仕上げる。敷地東辺の重厚さと趣を異とし、軽快な印象を備えた長大な門塀である","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010419"},{"id":"00001858","register_sub_id":"101","register_pk":"102848","name":"湯田家住宅主屋","kana":"ゆだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町中荒井字久宝居744","lat":37.17934754,"lng":139.75153446,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、鉄板葺、建築面積248㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"07 － 0044","desc":"会津鉄道中荒井駅の東方，国道１２１号線沿いの東西に長い敷地の西寄りに建つ。もと桁行９間半，梁行５間，寄棟造，茅葺の直屋の北側ニワ東方に増築して曲屋風にし，東面をかぶと造風に造る。内部は，南側カミテの座敷奥を仏壇の間としている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001858"},{"id":"00001859","register_sub_id":"101","register_pk":"102849","name":"湯田家住宅土蔵","kana":"ゆだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町中荒井字久宝居744","lat":37.17938546,"lng":139.75147316,"geo_status":"db","era":"文久2","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"07 － 0045","desc":"主屋の西方，国道１２１号線に沿って建つ。もとは国道上に在り，明治１６年の道路開削により現在地に曳家されている。南北棟，切妻造，鉄板葺，置屋根型式の土蔵で，現在は腰に大谷石を張りまわす。棟木の墨書により，越後の棟梁井村與惣次の名が知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001859"},{"id":"00002355","register_sub_id":"101","register_pk":"103345","name":"若喜商店座敷蔵","kana":"わかきしょうてんざしきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市字3-4786","lat":37.65015,"lng":139.871475,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木骨煉瓦造2階建、瓦葺、建築面積30㎡","structure_material":"木骨煉瓦造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"07 － 0060","desc":"煉瓦蔵の東に接続して建つ。木骨煉瓦造，２階建で，東面には２階をバルコニー風に造った玄関ポーチを付属する。内部座敷は１階を縞柿，２階を欅を中心とした銘木で造作する。外回りの軒や胴蛇腹の飾積みも３階蔵よりさらに華やかである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002355"},{"id":"00002354","register_sub_id":"101","register_pk":"103344","name":"若喜商店煉瓦蔵","kana":"わかきしょうてんれんがぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市字3-4786","lat":37.650124,"lng":139.871567,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"煉瓦造3階建、瓦葺、建築面積46㎡","structure_material":"煉瓦造3階建","registered":"2001.10.12(平成13.10.12)","register_no":"07 － 0059","desc":"店舗の背後に続き，脇道に面して建つ煉瓦造３階建の道具蔵。喜多方で操業した煉瓦工場で製造された煉瓦を用い民間で初めて建設されたもので，当地に煉瓦建築を普及させた田中又一の施工になるという。軒の飾積みなどに精緻な仕事が見られ，保存状態もよい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002354"},{"id":"00008257","register_sub_id":"101","register_pk":"133899","name":"若菜家住宅煉瓦作業蔵","kana":"わかなけじゅうたくれんがさぎょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県喜多方市岩月町宮津字勝耕作3819","lat":37.68131871,"lng":139.90329689,"geo_status":"db","era":"明治43年／昭和7年増築・昭和60年頃改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積138㎡","structure_material":"煉瓦造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"07 － 0119","desc":"敷地東南隅に位置する煉瓦造２階建。桁行１３ｍ梁間６．０ｍで、西・南・北に下屋を付設する。南北棟の切妻造桟瓦葺で、西面下屋中央に一段高く切妻造屋根を設ける。下屋にアーチの開口を連続させ、施釉煉瓦を使い分けるなど、変化のある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008257"},{"id":"00008255","register_sub_id":"101","register_pk":"133897","name":"若菜家住宅煉瓦座敷蔵","kana":"わかなけじゅうたくれんがざしきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県喜多方市岩月町宮津字勝耕作3819","lat":37.68155634,"lng":139.90302695,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積37㎡","structure_material":"煉瓦造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"07 － 0117","desc":"通りの東に占める敷地の通り沿いに南北棟で建つ。切石積基礎上にイギリス積とする煉瓦造平屋建。角に柱型を造り、通り側に半円アーチ窓、東側に欠円アーチの出入口を設ける。内部は縁と座敷、茶室などを配する。軸部を漆塗とするなど良質な座敷蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008255"},{"id":"00008256","register_sub_id":"101","register_pk":"133898","name":"若菜家住宅煉瓦三階蔵","kana":"わかなけじゅうたくれんがさんがいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県喜多方市岩月町宮津字勝耕作3819","lat":37.68150311,"lng":139.90299463,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造3階建、瓦葺、建築面積31㎡","structure_material":"煉瓦造3階建","registered":"2010.09.10(平成22.09.10)","register_no":"07 － 0118","desc":"煉瓦座敷蔵の南に位置する。桁行５．７ｍ梁間４．８ｍの煉瓦造３階建。東西棟の切妻造桟瓦葺で、東面にポーチを付設する。切石積基礎上にイギリス積とし、角に柱型をつくる。南面２、３階には石造のアーチ窓を穿つ。煉瓦蔵が集中する地域における象徴的な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008256"},{"id":"00008258","register_sub_id":"101","register_pk":"133900","name":"若菜家住宅煉瓦味噌蔵","kana":"わかなけじゅうたくれんがみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"福島県","address":"福島県喜多方市岩月町宮津字勝耕作3819","lat":37.68135293,"lng":139.90314101,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積26㎡","structure_material":"煉瓦造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"07 － 0120","desc":"敷地南辺に東西棟で建つ。桁行８．６ｍ梁間３．０ｍの煉瓦造平屋建で、切妻造桟瓦葺とする。切石積基礎上、長手積とし、角などに柱型をつくり、軒まわりは漆喰塗とする。内部は東西二室に分かれ、各出入口をアーチ型に穿ち、瓦を飾る。丁寧な仕上げになる煉瓦蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008258"},{"id":"00013498","register_sub_id":"101","register_pk":"504862","name":"渡部家住宅馬小屋","kana":"わたなべけじゅうたくうまごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福島県","address":"福島県双葉郡大熊町大字大川原字南平275","lat":37.38385833,"lng":140.95673611,"geo_status":"db","era":"昭和前期／昭和37年頃改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積96㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"07 － 0244","desc":"敷地北東に西面して建つ。南北棟で二階建切妻造セメント瓦葺の比較的大規模な建物。真壁造で南・東面に下屋、二階西面に縁を張出す。小屋はキングポストトラス。一階を馬屋、二階を飼料置場としたと思われ、後年居室に整備。馬産で栄えた当家の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013498"},{"id":"00013497","register_sub_id":"101","register_pk":"504861","name":"渡部家住宅主屋","kana":"わたなべけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県双葉郡大熊町大字大川原字南平275","lat":37.38391944,"lng":140.95654167,"geo_status":"db","era":"明治前期／昭和37年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積193㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"07 － 0243","desc":"大熊町西方の内陸部に位置し、主屋は敷地の北奥に建つ。平屋建、入母屋造。軒はせがい造のもと茅葺で、桟瓦葺とした際に小屋組を改修した。玄関奥をイマ等として上手は二列六室で縁を廻し、下手は土間を板敷に整備。地域に残る大規模な農家主屋として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013497"},{"id":"00004908","register_sub_id":"101","register_pk":"105898","name":"渡辺家住宅北蔵","kana":"わたなべけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県須賀川市梅田字岩瀬85","lat":37.31661759,"lng":140.22617386,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、鉄板葺、建築面積20㎡","structure_material":"土蔵造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"07 － 0080","desc":"主屋北側に東西棟で建ち，桁行３間，梁間２間の規模で，切妻造，鉄板葺，東妻面に引戸を開く。大谷石の基礎の上に建ち，漆喰塗で，置屋根形式とする。主屋土間背口前に位置する味噌蔵として使われ，窓のない小規模な蔵であるが，往時の生活を知る上で貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004908"},{"id":"00003054","register_sub_id":"101","register_pk":"104044","name":"渡部家住宅主屋","kana":"わたなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町糸沢字今泉平896","lat":37.14209997,"lng":139.73105854,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積165㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"07 － 0069","desc":"会津茅手と言う茅葺職人を輩出した地域にある集落のひとつ，今泉のほぼ中央に所在する。当地方では鍵屋と呼ばれる座敷部分の棟と土間部分の棟を直交させた曲家風で，柱に栗材を多く用い，鉄板覆の屋根も茅葺の形をとどめ，江戸後期の民家の形式を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003054"},{"id":"00003055","register_sub_id":"101","register_pk":"104045","name":"渡部家住宅土蔵","kana":"わたなべけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町糸沢字今泉平896","lat":37.14210815,"lng":139.73101284,"geo_status":"db","era":"文政4","year":1821,"year_source":"db","year_min":1821,"year_max":1821,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積10㎡","structure_material":"土蔵造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"07 － 0070","desc":"主屋の後方，敷地西北に建つ桁行２間，梁間１間半の小規模な土蔵で，味噌等の貯蔵に用いられた。地棟に文政２年の墨書がある。屋根は置き屋根式の切妻造・鉄板葺であるが，かなり急勾配で，妻面には頑丈な戸前庇を設けるなど，多雪地帯らしい造形がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003055"},{"id":"00013499","register_sub_id":"101","register_pk":"504863","name":"渡部家住宅土蔵","kana":"わたなべけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県双葉郡大熊町大字大川原字南平275","lat":37.38370556,"lng":140.95645833,"geo_status":"db","era":"明治前期／昭和37年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"07 － 0245","desc":"敷地中央に北面して建つ。南北棟とし二階建切妻造でセメント瓦葺の置屋根を載せる。腰を海鼠壁、上部を漆喰塗とし、戸口や窓の土戸外部を黒漆喰塗とする等正面構えに意匠を凝らす。小屋は登梁形式で内部は用途に応じて仕上を変える。敷地の一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013499"},{"id":"00004906","register_sub_id":"101","register_pk":"105896","name":"渡辺家住宅東蔵","kana":"わたなべけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県須賀川市梅田字岩瀬85","lat":37.31638627,"lng":140.22634035,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積22㎡","structure_material":"土蔵造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"07 － 0078","desc":"主屋の土間出入口の南東に北面して建ち，桁行３間，梁間２間，切妻造，桟瓦葺，妻入，平屋建。北面２間に下屋庇を差し掛け，観音開きの土扉を開く。鬼瓦を乗せた置屋根とし，外壁は腰に海鼠壁を廻し，上部は漆喰塗りとする。優れた左官仕事は見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004906"},{"id":"00004907","register_sub_id":"101","register_pk":"105897","name":"渡辺家住宅南蔵","kana":"わたなべけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県須賀川市梅田字岩瀬85","lat":37.31638451,"lng":140.22611042,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"07 － 0079","desc":"主屋の南西に東面して建ち，桁行４間半，梁２間半，切妻造，桟瓦葺，平入，土蔵造２階建で，東面に下屋庇を差し掛けて引戸を開く。外壁は中塗仕上げで，正面以外を下部板張とし，袴腰を廻す。妻面の１，２階に窓を開く。規模の大きな置屋根をもつ土蔵として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004907"},{"id":"00013500","register_sub_id":"101","register_pk":"504864","name":"渡部家住宅籾蔵","kana":"わたなべけじゅうたくもみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県双葉郡大熊町大字大川原字南平275","lat":37.38368889,"lng":140.95677778,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、鉄板葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"07 － 0246","desc":"表門の東脇に建つ小規模な板蔵。東西棟とし平屋建切妻造妻入で鉄板葺の置屋根を載せる。外壁、内部の間仕切壁とも柱の板溝に横板をはめた板壁とする。小屋は桁行中央の柱位置に梁を架け、束で棟木を受ける。垂木は半割丸太。敷地前方の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013500"},{"id":"00013501","register_sub_id":"101","register_pk":"504865","name":"渡部家住宅薬医門及び塀","kana":"わたなべけじゅうたくやくいもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県双葉郡大熊町大字大川原字南平275","lat":37.38358611,"lng":140.95675833,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"門 木造、瓦葺、間口2.4m、塀 木造、鉄板葺、総延長38m","structure_material":"門 木造","registered":"2021.02.04(令和3.02.04)","register_no":"07 － 0247","desc":"敷地南の前面道路に面して門を構え、左右に塀を延ばす。薬医門は切妻造桟瓦葺で、戸は建てず開放とする。塀は門の両脇の板塀と、矩折れに延長する石積上に建つ板塀からなり、総延長三八メートルである。東日本大震災に耐えた豪農の表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013501"},{"id":"00000427","register_sub_id":"101","register_pk":"101417","name":"石名坂家住宅蔵","kana":"いしなざかけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県鶴岡市大字加茂字加茂54","lat":38.76231699,"lng":139.73555943,"geo_status":"db","era":"嘉永3頃","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積50㎡","structure_material":"土蔵造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"06 － 0026","desc":"主屋の後方に蔵前を介して隣接して建つ。周囲を板壁（現在は一部がトタン等に改造）のサヤで覆う。内部は，主屋と同じく各部材を透漆で塗る豪華なつくりになる。主屋とともに加茂町の伝統的な住宅の屋敷構えを構成する一要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000427"},{"id":"00000426","register_sub_id":"101","register_pk":"101416","name":"石名坂家住宅主屋","kana":"いしなざかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県鶴岡市大字加茂字加茂54","lat":38.76244793,"lng":139.73538087,"geo_status":"db","era":"嘉永3","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造平屋建一部2階建，瓦葺，建築面積127㎡","structure_material":"木造平屋建一部2階建","registered":"1998.01.16(平成10.01.16)","register_no":"06 － 0025","desc":"北前船の中継港として栄えた加茂町に建つ船持の家（廻船主）の住宅。正面妻壁軒下の航海安全を祈る祈祷札がそれを物語る。間口が狭く奥行の長い敷地は加茂町によくみられるもので，外観は簡素だが内部は部材全体に透漆を施す等とくに豪華なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000426"},{"id":"00002505","register_sub_id":"101","register_pk":"103495","name":"市島家住宅蔵","kana":"いちじまけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県山形市七日町5-10-53","lat":38.25094038,"lng":140.34183493,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造2階建、亜鉛メッキ銅板葺、建築面積62㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"06 － 0041","desc":"店舗の後方にあり，棟札より明治４３年の建築と判明する。切妻造・平入の２階建土蔵で，屋根は東西棟・鉄板葺とする。内部は１階を畳敷で数寄屋風の和室とし，２階は物置である。外壁は重厚な漆喰塗で，開口部上部の梁型や観音扉など丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002505"},{"id":"00008805","register_sub_id":"101","register_pk":"162248","name":"蟹仙洞旧長谷川家住宅主屋","kana":"かいせんどうきゅうはせがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県上山市矢来4-111他","lat":38.14922582,"lng":140.27888051,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、スレート葺、建築面積274㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"06 － 0123","desc":"敷地中央に建ち、木造二階建、建築面積274㎡、入母屋造スレート葺で、西面に玄関、南面に台所を突出させる。伝統的な和風住宅のつくりを基本に、建ちを高くし、周囲の廊下にガラス戸を建てて開放的につくるなど、近代的な趣のある大型住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008805"},{"id":"00008806","register_sub_id":"101","register_pk":"162249","name":"蟹仙洞旧長谷川家住宅東土蔵","kana":"かいせんどうきゅうはせがわけじゅうたくひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県上山市矢来4-1233他","lat":38.14906306,"lng":140.27901833,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、瓦葺、建築面積101㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"06 － 0124","desc":"敷地東側に建ち、主屋と廊下で繋ぐ。桁行9.4ｍ梁間5.6ｍ、土蔵造二階建、切妻造妻入瓦葺の主体部の北妻に展示室玄関、西面に和室展示室を張出す。外部は腰を洗出し仕上げとして南妻に鉄扉を開く。重厚な外観で、敷地景観を引き締めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008806"},{"id":"00008807","register_sub_id":"101","register_pk":"162250","name":"蟹仙洞旧長谷川家住宅南土蔵","kana":"かいせんどうきゅうはせがわけじゅうたくみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県上山市矢来4-1233他","lat":38.14899059,"lng":140.278852,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、鉄板葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"06 － 0125","desc":"敷地南側に建ち、桁行9.5ｍ梁間4.7ｍ、土蔵造2階建、切妻造、置屋根式鉄板葺である。1階は北面を出入口として庇を付け、この他にも開口部を三ヶ所設ける。外部は漆喰塗で、開口部の枠は掛子塗で丁寧に仕上げ、東面を簓子下見板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008807"},{"id":"00001103","register_sub_id":"101","register_pk":"102093","name":"風間家旧宅（丙申堂）表門","kana":"かざまけきゅうたく（へいしんどう）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県鶴岡市馬場町1-15","lat":38.72821431,"lng":139.82952861,"geo_status":"db","era":"江戸期","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"木造薬医門，瓦葺","structure_material":"木造薬医門","registered":"1999.06.07(平成11.06.07)","register_no":"06 － 0031","desc":"もと庄内藩要職者の居宅の屋敷門で、明治２７年の酒田地震にも耐え残ったもの。３間×２間の薬医門形式の門で、正面扉の右脇に潜り戸を設ける。鶴岡における武家住宅の屋敷構えを今に伝える遺構のひとつとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001103"},{"id":"00001104","register_sub_id":"101","register_pk":"102094","name":"風間家旧宅（丙申堂）西側板塀","kana":"かざまけきゅうたく（へいしんどう）にしがわいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県鶴岡市馬場町1-15","lat":38.72866735,"lng":139.82885329,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造，鉄板葺，延長27.7m","structure_material":"木造","registered":"1999.06.07(平成11.06.07)","register_no":"06 － 0035","desc":"敷地の西端を限る板塀で、中蔵・奥蔵の鞘西面に沿って残る。低い石積基壇に土台建ちの板塀を建て、内側に控えをとる形式で、鉄板葺の小屋根を載せて街路景観を整えている。屋敷地外構の面影を今に伝えていることで貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001104"},{"id":"00003351","register_sub_id":"101","register_pk":"104341","name":"風間家旧別邸無量光苑板塀","kana":"かざまけきゅうべっていむりょうこうえんいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県鶴岡市泉町6-20","lat":38.7296585,"lng":139.8292486,"geo_status":"db","era":"明治43頃／昭和29移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造、鉄板葺、延長62m","structure_material":"木造","registered":"2003.07.01(平成15.07.01)","register_no":"06 － 0057","desc":"敷地の西面を区切る塀。高さ約２．１ｍで，礎石上に土台を置き，１．８ｍ毎に立つ柱を４段の貫で固め，敷地内に控えを取る。北方１箇所に大戸付の戸口を設ける。小屋根を載せ竪板張の簡素な板塀だが，通りに沿って一直線に長く続く姿は屋敷構えを特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003351"},{"id":"00003348","register_sub_id":"101","register_pk":"104338","name":"風間家旧別邸無量光苑表門","kana":"かざまけきゅうべっていむりょうこうえんおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県鶴岡市泉町6-20","lat":38.72934935,"lng":139.829269,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造、瓦葺、間口2.1m、左右袖塀付","structure_material":"木造","registered":"2003.07.01(平成15.07.01)","register_no":"06 － 0054","desc":"敷地南面東端部に開く。薬医門形式で角柱の本柱上に太い冠木を置き，男梁を載せて半繁垂木の屋根を受ける。本柱に続いてハ字型に簓子下見張，大和葺の袖塀を付属する。小規模だが精緻な造りで，棟上に鯱型の飾瓦を置いて飾るなど，表門に相応しい格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003348"},{"id":"00003350","register_sub_id":"101","register_pk":"104340","name":"風間家旧別邸無量光苑北門","kana":"かざまけきゅうべっていむりょうこうえんきたもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県鶴岡市泉町6-20","lat":38.72987242,"lng":139.82944017,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、鉄板葺、間口2.1m","structure_material":"木造","registered":"2003.07.01(平成15.07.01)","register_no":"06 － 0056","desc":"屋敷北西部，敷地北辺を限る外堀から約３．６ｍ入り込んで建つ。間口約２．１ｍの腕木門で，戸口に両開板戸，冠木上は襷桟を打って仕切る。簡素で小規模な門だが，大振りな礎石を用いた丁寧な造作で，軸吊の八双金具や饅頭金具等細部にも見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003350"},{"id":"00002602","register_sub_id":"101","register_pk":"103592","name":"風間家旧別邸無量光苑釈迦堂","kana":"かざまけきゅうべっていむりょうこうえんしゃかどう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県鶴岡市泉町6-20","lat":38.72946586,"lng":139.8294101,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"06 － 0042","desc":"来賓の接待などに用いられた別邸で，重要文化財旧風間家住宅の近くにある。平面は座敷２室と前室からなり，西面に玄関，東面と北面に広縁と土庇を設け，入母屋造の屋根を架ける。良材を用いた数寄屋風建築で，小規模だが質の高いつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002602"},{"id":"00003349","register_sub_id":"101","register_pk":"104339","name":"風間家旧別邸無量光苑中門","kana":"かざまけきゅうべっていむりょうこうえんちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県鶴岡市泉町6-20","lat":38.72948817,"lng":139.82933,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造、鉄板葺、間口1.1m、左右袖塀付","structure_material":"木造","registered":"2003.07.01(平成15.07.01)","register_no":"06 － 0055","desc":"釈迦堂玄関脇の内苑を仕切る門で，左右に袖板塀を付属する。茶室脇にあり露地門の性格も持つ。間口１ｍ程の小規模な腕木門だが，引戸表側は矢筈に板を張り，屋根は大きく起りを付け破風に繰形を彫るなど随所に趣向を凝らす。屋敷導入部の景観に欠かせない門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003349"},{"id":"00003347","register_sub_id":"101","register_pk":"104337","name":"風間家旧別邸無量光苑土蔵","kana":"かざまけきゅうべっていむりょうこうえんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県鶴岡市泉町6-20","lat":38.729347,"lng":139.829651,"geo_status":"db","era":"明治30頃／昭和30移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"06 － 0053","desc":"もと南側道路を隔てた本邸にあった内蔵を移築したもので，敷地南東隅に建つ。２階建，置屋根形式の土蔵造で，桁行４間，梁間２間半の比較的小規模だが，良材を用い，１・２階とも密に柱を立てた堅牢な造りになる。内部木部は漆塗で，金具等にも意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003347"},{"id":"00014312","register_sub_id":"101","register_pk":"511301","name":"旧松岡家住宅後の蔵","kana":"きゅうまつおかけじゅうたくうしろのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市歌丸字窪二1629","lat":38.05590278,"lng":140.02704444,"geo_status":"db","era":"明治32年／昭和中期改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造平屋一部2階建、鉄板葺、建築面積46㎡","structure_material":"土蔵造平屋一部2階建","registered":"2022.10.31(令和4.10.31)","register_no":"06 - 0205","desc":"主屋の北西に東面し、道具や米を収納する土蔵。二階建、切妻造平入で、屋根は鉄板葺の置屋根形式。外壁は中塗仕上で、南西面は鉄板張で養生する。東面に戸口を設け、内部は二室で北を土間、南を板敷とし、上部に二階を設ける。敷地西側の景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014312"},{"id":"00014310","register_sub_id":"101","register_pk":"511299","name":"旧松岡家住宅主屋","kana":"きゅうまつおかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市歌丸字窪二1629","lat":38.05567778,"lng":140.02706111,"geo_status":"db","era":"江戸後期／平成12年・令和2年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"06 - 0203","desc":"長井市街南郊の農村に所在する農家。主屋は敷地中央に東面する平屋建、寄棟造茅葺で、東面中央に煙出しの破風を付す。東面には南北二箇所の戸口を設け、内部は南に床付座敷を配す。屋敷地周囲に田園が広がり、茅葺屋根が農村地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014310"},{"id":"00014311","register_sub_id":"101","register_pk":"511300","name":"旧松岡家住宅前蔵","kana":"きゅうまつおかけじゅうたくまえぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県長井市歌丸字窪二1629","lat":38.05570556,"lng":140.02734167,"geo_status":"db","era":"明治20年／昭和中期改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積32㎡","structure_material":"土蔵造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"06 - 0204","desc":"主屋の南東に西面し、籾を収納する土蔵。平屋建切妻造平入で、屋根は鉄板葺の置屋根形式。外壁は中塗仕上で、西面に戸口を設けて下屋を付す。内部中央は土間で、両脇に床・壁・天井を板張、落とし板で開け閉めする穀櫃を配す。米農家の屋敷構えをつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014311"},{"id":"00004109","register_sub_id":"101","register_pk":"105099","name":"大泉坊長屋門","kana":"だいせんぼうながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県飽海郡遊佐町上蕨岡字常盤森1","lat":38.99632112,"lng":139.94252635,"geo_status":"db","era":"天保5頃","year":1834,"year_source":"db","year_min":1834,"year_max":1834,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"06 － 0058","desc":"大物忌神社参道に南面して建つ。桁行１８．６８ｍ梁間４．５４ｍ規模，入母屋造，桟瓦葺で，西寄りに門口を開き，東側に土間の物置（もと米蔵），西側に床上部を配する。軸部は欅材で造り，軒は出桁造，一軒疎垂木とする。地区集落の景観上要となる建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004109"},{"id":"00011244","register_sub_id":"101","register_pk":"209079","name":"多勢丸中家住宅座敷棟","kana":"たせまるなかけじゅうたくざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県南陽市池黒字川原1430他","lat":38.07025,"lng":140.12405,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"06－0180","desc":"屋敷地中央の庭の西側に建つ、南北棟の入母屋造銅板葺。北側客間の床は両側に床脇を備え、框二段とする凝った造り。生糸の商談に来訪した外国人等をもてなすために建てたと伝え、良材を用い、金銀泥引き唐紙貼の壁、欄間、金具などすべてが豪奢である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011244"},{"id":"00011245","register_sub_id":"101","register_pk":"209080","name":"多勢丸中家住宅洋館","kana":"たせまるなかけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県南陽市池黒字川原1430他","lat":38.070237,"lng":140.123934,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、銅板葺、建築面積64㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"06－0181","desc":"座敷棟の西側に接続する応接用の建築。座敷側屋根を切妻、西側は寄棟とし、ドーマー窓を設ける。外壁は下見板張で、1階は引違い出窓、二階は上下窓とするなど外観を洋風でまとめる。一階内部は手の込んだ和風。階段室と二階は洋風で、優れた意匠と技術を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011245"},{"id":"00007336","register_sub_id":"101","register_pk":"108318","name":"田中家住宅座敷蔵","kana":"たなかけじゅうたくざしきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県山形市陣場1-22他","lat":38.27750472,"lng":140.31131383,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、鉄板葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"06 － 0107","desc":"ナンド北面に蔵前を介して繋がる。桁行９．１ｍ梁間５．１ｍの妻入２階建土蔵で、北面に下屋を設ける。切妻造鉄板葺の置屋根とし、外壁を漆喰で仕上げ、腰に下見板を張る。１階は続き座敷で、良質な意匠になる座敷飾りを備える。直材による独特の小屋架構をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007336"},{"id":"00007335","register_sub_id":"101","register_pk":"108317","name":"田中家住宅主屋","kana":"たなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県山形市陣場1-22他","lat":38.27739062,"lng":140.31126948,"geo_status":"db","era":"明治前期／昭和47改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、茅葺（鉄板仮葺）、建築面積201㎡","structure_material":"木造平屋一部2階建","registered":"2008.10.23(平成20.10.23)","register_no":"06 － 0106","desc":"通りに北側に占める敷地の前寄りに南面して建つ。桁行９間半梁間５間規模の木造２階建で、茅葺の上に鉄板を葺く。西側に土間や台所、東半部にジョウダンノマなど４室を田の字に配し、背面にナンドを付け、２階に座敷などを置く。風格ある近代農家建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007335"},{"id":"00007337","register_sub_id":"101","register_pk":"108319","name":"田中家住宅漬物蔵","kana":"たなかけじゅうたくつけものぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県山形市陣場1-22他","lat":38.27745083,"lng":140.3111911,"geo_status":"db","era":"明治前期／昭和30改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、鉄板葺、建築面積10㎡","structure_material":"土蔵造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"06 － 0108","desc":"主屋北面の西寄りに接続する。桁行３．９ｍ梁間２．５ｍと小規模な妻入平屋建土蔵で、切妻造鉄板葺の屋根が載る。外壁は白漆喰仕上げで、腰板を張る。南妻面に主屋からの出入口、北面には窓を開ける。内部は一室で、和小屋。漬物の保管等に使われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007337"},{"id":"00007338","register_sub_id":"101","register_pk":"108320","name":"田中家住宅道具蔵","kana":"たなかけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県山形市陣場1-22他","lat":38.277241,"lng":140.311371,"geo_status":"db","era":"明治9","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積21㎡","structure_material":"土蔵造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"06 － 0109","desc":"主屋の南東に位置し、道路脇水路に接して建つ。桁行５．６ｍ梁間３．７ｍの土蔵造平屋建で、切妻造鉄板葺の置屋根を載せる。西面中央に庇を設け出入口とし、北面に窓を開ける。外壁は段を付けた白漆喰仕上げとし、腰に下見板を張る。座敷蔵と同様の架構をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007338"},{"id":"00007339","register_sub_id":"101","register_pk":"108321","name":"田中家住宅門及び塀","kana":"たなかけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県山形市陣場1-22他","lat":38.27729518,"lng":140.31102146,"geo_status":"db","era":"昭和9頃","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"門 木造、銅板葺、間口4.3m 塀 木造、鉄板葺及び銅板葺、延長68m","structure_material":"門 木造","registered":"2008.10.23(平成20.10.23)","register_no":"06 － 0110","desc":"門は主屋の正面に建つ、間口４．３ｍの腕木門。起りのある切妻造銅板葺で、両袖塀にも屋根をかける。塀は門袖塀から東西に延びるとともに、敷地内部の庭塀にも続き、延長６８ｍに及ぶ。上部漆喰仕上げ、腰竪板張とする。街道沿いの伝統的な景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007339"},{"id":"00014315","register_sub_id":"101","register_pk":"511304","name":"近岡家住宅主屋","kana":"ちかおかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県最上郡金山町大字飛森字谷口493","lat":38.90389444,"lng":140.31073889,"geo_status":"db","era":"江戸末期／昭和初期・同45年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、鉄板葺、建築面積311㎡","structure_material":"木造平屋一部2階建","registered":"2022.10.31(令和4.10.31)","register_no":"06 - 0208","desc":"金山町市街から北西の農村に所在する農家。主屋は南面する大規模な中門造で、西に七室を並べ、東に馬屋中門を突出し、南面西寄りに式台を設ける。かつて屋根は茅葺で、南面側通りに三本溝の鴨居を留め、古式を残す。山形県北部の中門造民家の発展を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014315"},{"id":"00006700","register_sub_id":"101","register_pk":"107683","name":"出羽桜美術館旧仲野家住宅蔵","kana":"でわざくらびじゅつかんきゅうなかのけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県天童市一日町1-315-1","lat":38.349606,"lng":140.370682,"geo_status":"db","era":"明治45／昭和62移築","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積105㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"06 － 0095","desc":"主屋の左手に、軒面を揃えて建つ。切妻造妻入桟瓦葺の土蔵で、桁行５間梁間３間規模になり、両妻側に蔵前を設ける。外観は漆喰仕上げとし、平側には土戸両開の窓を３ヶ所に穿つ。２階が物置で、１階はトコと違棚がある書院風座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006700"},{"id":"00006740","register_sub_id":"101","register_pk":"107723","name":"出羽桜美術館旧仲野家住宅主屋","kana":"でわざくらびじゅつかんきゅうなかのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県天童市一日町1-315-1","lat":38.34964,"lng":140.370819,"geo_status":"db","era":"明治45／昭和初期増築・昭和62移築","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積311㎡","structure_material":"木造平屋一部2階建","registered":"2007.12.05(平成19.12.05)","register_no":"06 － 0094","desc":"旧羽州街道西側の敷地に建つ。寄棟造平入桟瓦葺で、正・側・背面に下屋庇を設ける。桁行１１間梁間５間規模で、左手に土間、板敷を介して右手に前後各３室の畳敷を設け、背面に座敷や離れを付設する。老舗商家にふさわしい、風格ある佇まいをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006740"},{"id":"00000627","register_sub_id":"101","register_pk":"101617","name":"土門家住宅主屋","kana":"どもんけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県飽海郡遊佐町小松字長田15-1","lat":39.00006581,"lng":139.91814934,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建，瓦葺，建築面積156㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"06 － 0030","desc":"酒田の大地主であった本間家の差配人を勤めた家柄の住宅で，１９世紀中頃の建造と推定される。茅葺の上に鉄板をかぶせ，内装を主とした改造はあるものの，中門造りとしての間取り構成や主体構造はこの地域の民家の特徴をよく伝えており貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000627"},{"id":"00000019","register_sub_id":"101","register_pk":"101009","name":"橋本家住宅主屋","kana":"はしもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県酒田市日吉町2-3-25","lat":38.91735905,"lng":139.83191065,"geo_status":"db","era":"明治37頃","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積485㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"06 － 0002","desc":"明治27年の地震時の大火で焼失した後，10年をかけて建設したと伝える酒造業を営む平入の町家。通り土間をとり道側に座敷，裏側に板敷の大きな部屋がある酒田の伝統的大規模町家の系統をひく建物で，規模や材質等の点においてその代表的事例のひとつといえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000019"},{"id":"00003050","register_sub_id":"101","register_pk":"104040","name":"吉亭北土蔵","kana":"よしていきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県米沢市門東町1-3-46","lat":37.90510676,"lng":140.10757572,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造地上3階地下1階建、亜鉛葺、建築面積46㎡","structure_material":"土蔵造地上3階地下1階建","registered":"2003.01.31(平成15.01.31)","register_no":"06 － 0049","desc":"敷地北寄り，本屋の背面に廊下等を介して連続して建つ。南北棟の切妻造・銅板葺，木造・３階建で，地下室も備える。外壁は下半を海鼠壁，上半を漆喰塗とし，東面には各階２つの観音扉付き小窓を整然と並べる。本屋同様，街路景観上，際だった存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003050"},{"id":"00003049","register_sub_id":"101","register_pk":"104039","name":"吉亭本屋","kana":"よしていほんや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県米沢市門東町1-3-46","lat":37.90494755,"lng":140.10763896,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、瓦葺、建築面積343㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"06 － 0048","desc":"西辺が旧会津道に接した敷地西寄りに，南面して建つ。木造・２階建，南北棟の寄棟造・桟瓦葺で，南・西・北に庇を廻し，南面には切妻造の玄関を設ける。内部の柱や造作材に秋田杉を多用した質の高いつくりで，風格のある外観は地域の景観の核になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003049"},{"id":"00003051","register_sub_id":"101","register_pk":"104041","name":"吉亭南土蔵","kana":"よしていみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県米沢市門東町1-3-46","lat":37.90476766,"lng":140.10773486,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、亜鉛葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"06 － 0050","desc":"大正８年の米沢大火でも焼失を免れた。敷地のほぼ中央，本屋の南方に建つ東西棟の切妻造・鉄板葺，木造・２階建で，漆喰塗の外壁は腰を海鼠壁とし，北面には戸口，南・西面に観音扉付き小窓を設ける。生糸の保管等に用いられた丁寧なつくりの土蔵建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003051"},{"id":"00003052","register_sub_id":"101","register_pk":"104042","name":"吉亭門","kana":"よしていもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県米沢市門東町1-3-46","lat":37.9048539,"lng":140.10750189,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2003.01.31(平成15.01.31)","register_no":"06 － 0051","desc":"旧会津道に接した敷地西辺に設けられた門で，本屋の南玄関に至るアプローチとなっている。間口約２．６ｍの１間１戸薬医門形式で，屋根は切妻造・桟瓦葺，左右に袖塀をつける。上質の欅材をふんだんに用い，街路景観に重厚な雰囲気をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003052"},{"id":"00000183","register_sub_id":"101","register_pk":"101173","name":"米沢市上杉記念館大広間・玄関棟","kana":"よねざわしうえすぎきねんかんおおひろま・げんかんとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県米沢市丸の内1-3-60","lat":37.90761825,"lng":140.10514168,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積426㎡","structure_material":"木造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"06 － 0007","desc":"旧上杉伯爵邸を記念館としたもの。木造・一部２階建になる純和風の建物で、吟味された材料を用いた上質な造りになる。設計は中條精一郎、施行は上杉家出入りの江部栄蔵。外観は延びのある入母屋屋根と庇の間に真壁を見せる清廉な意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000183"},{"id":"00000381","register_sub_id":"101","register_pk":"101371","name":"米沢市上杉記念館北土蔵","kana":"よねざわしうえすぎきねんかんきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県米沢市丸の内1-3-60","lat":37.90788691,"lng":140.10481797,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積45㎡","structure_material":"土蔵造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"06 － 0023","desc":"東土蔵と同様の構造になり，開口部の構成も類似するが，規模は一回り小さい。元は上杉家関係の文書や美術品等の収蔵にあてられたといわれる。置き屋根形式になる屋根の軒廻りを板張りとし，腰下には下見板を張る。東土蔵とともに屋敷構えの構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000381"},{"id":"00000184","register_sub_id":"101","register_pk":"101174","name":"米沢市上杉記念館客間棟","kana":"よねざわしうえすぎきねんかんきゃくまとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県米沢市丸の内1-3-60","lat":37.90755026,"lng":140.1049395,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建，銅板葺，建築面積71㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"06 － 0008","desc":"大広間、玄関棟に接続して建つ２階建の建物。設計は中條精一郎、施行は上杉家出入りの江部栄蔵。洗練された巧みな大工技術を用いた質の高い建物である。全体に立ちが高く、側廻りの廊下及び１、２階の側廻りに設けた欄間が外観意匠を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000184"},{"id":"00000379","register_sub_id":"101","register_pk":"101369","name":"米沢市上杉記念館警護棟","kana":"よねざわしうえすぎきねんかんけいごとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県米沢市丸の内1-3-60","lat":37.90794847,"lng":140.10553235,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積54㎡","structure_material":"木造平屋建","registered":"1997.12.12(平成9.12.12)","register_no":"06 － 0021","desc":"記念館入り口の門脇に建つ入母屋造の建物で，もとは警察官が駐在するための施設であったが，現在は市観光協会が使用し観光案内等を行っている。規模は小さいが，延びのある入母屋屋根が特徴で，屋敷構えを知る上でも欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000379"},{"id":"00000377","register_sub_id":"101","register_pk":"101367","name":"米沢市上杉記念館子供室","kana":"よねざわしうえすぎきねんかんこどもしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県米沢市丸の内1-3-60","lat":37.90769265,"lng":140.10481216,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積130㎡","structure_material":"木造平屋建","registered":"1997.12.12(平成9.12.12)","register_no":"06 － 0019","desc":"上杉伯爵の旧宅を記念館としたもので，大広間棟など一連の建物は中條精一郎の設計，棟梁江部栄蔵の施工になる。子供室は，大広間・玄関棟の背面に接続して建つ平屋建の建物で，子供部屋２室・女中部屋２室等からなる。いずれも質の高い和風建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000377"},{"id":"00000378","register_sub_id":"101","register_pk":"101368","name":"米沢市上杉記念館使用人室","kana":"よねざわしうえすぎきねんかんしようにんしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県米沢市丸の内1-3-60","lat":37.90776534,"lng":140.10491617,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積91㎡","structure_material":"木造平屋建","registered":"1997.12.12(平成9.12.12)","register_no":"06 － 0020","desc":"大広間・玄関棟に接続し，その北東側に位置する入母屋造，平屋建を基本とした和風の建物。平面は，使用人室２室，女中室，台所等からなる。全体として簡素ながら，子供室同様に上質の杉材を用いた丁寧な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000378"},{"id":"00000380","register_sub_id":"101","register_pk":"101370","name":"米沢市上杉記念館東土蔵","kana":"よねざわしうえすぎきねんかんひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県米沢市丸の内1-3-60","lat":37.90795204,"lng":140.10507848,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積54㎡","structure_material":"土蔵造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"06 － 0022","desc":"凝灰岩の切石積基礎に建つ２階建の漆喰塗の土蔵で，妻入とする出入口はじめ全体的に開口部を小さくまとめあげる。もと米蔵として使用された。近年の改修で，腰下を石張風の仕上げとし瓦葺の屋根の両妻側のみ銅板葺とする。屋敷構えの一構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000380"},{"id":"00000185","register_sub_id":"101","register_pk":"101175","name":"米沢市上杉記念館仏間棟","kana":"よねざわしうえすぎきねんかんぶつまとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県米沢市丸の内1-3-60","lat":37.90751627,"lng":140.10481605,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積24㎡","structure_material":"木造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"06 － 0009","desc":"客間棟の西に接続して建つ宝形造りの建物。設計は中條精一郎、施行は上杉家出入りの江部栄蔵。６畳の間の背後に花唐窓風の縁取り壁を配した仏壇を設ける。簡素な建物ながら洗練された意匠になる質の高い純和様の建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000185"},{"id":"00000382","register_sub_id":"101","register_pk":"101372","name":"米沢市上杉記念館門","kana":"よねざわしうえすぎきねんかんもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"山形県","address":"山形県米沢市丸の内1-3-60","lat":37.90795928,"lng":140.10569357,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造一間薬医門，銅板葺","structure_material":"木造一間薬医門","registered":"1997.12.12(平成9.12.12)","register_no":"06 － 0024","desc":"記念館の正門として広く知られる大型の一間薬医門で，左右に袖塀が付く。反りのある延びやかな流れの屋根は，均整のとれた構成になるこの門を特徴付けている。各部の造りは正統的で，近代和風建築としての技術水準の高さを示す好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000382"},{"id":"00012097","register_sub_id":"101","register_pk":"352896","name":"渡邊六郎兵衛家住宅長屋門","kana":"わたなべろくろうべえけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県西置賜郡飯豊町大字黒沢字南舘1325","lat":38.05321,"lng":140.009915,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積137㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"06-190","desc":"敷地南面に建つ。中央の門口は上部に筬欄間を入れ格天井を張り格式ある意匠とする。東側の室は作業小屋で登梁形式、西側の室は家財道具を収納し天秤梁で棟木を受け、小屋組を異にする。腰を煉瓦貼とし、観音扉の窓を連続させ、集落の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012097"},{"id":"00003788","register_sub_id":"101","register_pk":"104778","name":"油伝味噌離れ","kana":"あぶでんみそはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市嘉右衛門町5-26","lat":36.38926512,"lng":139.73402622,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0091","desc":"敷地の南側に，文庫蔵と向き合う位置に建つ。桁行５間半梁間３間規模，切妻造，桟瓦葺の平屋建で，１０畳と６畳の２室から成り，北と南面に縁側を，北面東寄りに玄関を設ける。主室の１０畳は畳床と板床を備えた丁寧なつくり。３代伝兵衛の隠居所として建設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003788"},{"id":"00003785","register_sub_id":"101","register_pk":"104775","name":"油伝味噌文庫蔵","kana":"あぶでんみそぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市嘉右衛門町5-26","lat":36.389416,"lng":139.734055,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積41㎡","structure_material":"土蔵造3階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0088","desc":"旧例幣使街道の西側敷地の北側中程に東西棟で建つ。桁行５間梁間２間半，切妻造，桟瓦葺の内部３階建の内蔵で，石積基礎や防火戸など造りの丁寧さで際立つ。棟札から，当地土蔵造の名手として知られた三富清兵衛の作であることが判明している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003785"},{"id":"00003790","register_sub_id":"101","register_pk":"104780","name":"天海家住宅主屋","kana":"あまがいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県栃木市嘉右衛門町５他","lat":36.38596453,"lng":139.73316402,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0093","desc":"店舗西方背後に東西棟で建つ。主体部は桁行４間梁間２間半，入母屋造，桟瓦葺の木造２階建で，８畳２室から成る。店舗との繋ぎ部に玄関をとり，西南角から便所・風呂・台所を張り出す。２階南面に縁側を配し，全面にガラス戸を建込んだ開放的なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003790"},{"id":"00003791","register_sub_id":"101","register_pk":"104781","name":"天海家住宅土蔵","kana":"あまがいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市嘉右衛門町５他","lat":36.38598398,"lng":139.733017,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0094","desc":"主屋の西方に東西棟で建つ。桁行５間梁間２間半規模，切妻造，桟瓦葺の２階建土蔵で，南面に土間庇を差し掛け，２階に２箇所の窓を開ける。内部は２室に分け，東側を妻入の文庫蔵，西側を平入の荷蔵とする。墨書から「棟梁早川辰造」が判明している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003791"},{"id":"00003512","register_sub_id":"101","register_pk":"104502","name":"飯塚家住宅新宅裏門","kana":"いいづかけじゅうたくしんたくうらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県那須郡那珂川町馬頭字南町360","lat":36.73767678,"lng":140.16922375,"geo_status":"db","era":"明治40頃／昭和25頃改造","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、瓦葺、間口3.2m、石塀延長9.8m付","structure_material":"木造","registered":"2003.09.19(平成15.09.19)","register_no":"09 － 0083","desc":"敷地裏側の通りに面して建つ。控えを取った本柱に冠木を通して固め，腕木で桁を受け疎垂木を配り，桟瓦葺切妻屋根を戴く。簡明な構成だが良材を用いた上質なつくりで，裏門とはいえ大規模で格式ある形式を備える。屋敷背面の景観を整えるのに欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003512"},{"id":"00003511","register_sub_id":"101","register_pk":"104501","name":"飯塚家住宅新宅表門及び塀","kana":"いいづかけじゅうたくしんたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県那須郡那珂川町馬頭字南町３６０","lat":36.73713746,"lng":140.16944883,"geo_status":"db","era":"明治40頃／昭和25頃改造","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"表門 石造、間口3.5m、塀 木造、瓦葺、延長11m","structure_material":"表門 石造","registered":"2003.09.19(平成15.09.19)","register_no":"09 － 0082","desc":"表門は敷地正面中央の内側にやや控えて建つ。花崗岩を用い，基礎石上に門柱を立て，上にやや厚手の笠石を載せる。両脇は腰部大谷石積みとした桟瓦葺板塀が，門前をハ字に折れ曲りに仕切る。平明な意匠だが，広い門口や一石の高い門柱に当家の格式をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003511"},{"id":"00003507","register_sub_id":"101","register_pk":"104497","name":"飯塚家住宅新宅主屋","kana":"いいづかけじゅうたくしんたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県那須郡那珂川町馬頭字南町360","lat":36.73723831,"lng":140.16940704,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積170㎡、中門木戸及び前庭木戸付","structure_material":"木造平屋一部2階建","registered":"2003.09.19(平成15.09.19)","register_no":"09 － 0078","desc":"本宅西に隣接する新宅の主屋で，南北に長い敷地の南半部に南面して建つ。木造，一部２階建，寄棟造，桟瓦葺で，表側に広い玄関と表座敷を取り，後方に茶の間や奥座敷を配し，２階は女中部屋とする。整理された平面と座敷の進んだ意匠に近代的感覚が充溢する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003507"},{"id":"00003509","register_sub_id":"101","register_pk":"104499","name":"飯塚家住宅新宅中庭木戸","kana":"いいづかけじゅうたくしんたくなかにわきど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県那須郡那珂川町馬頭字南町360","lat":36.7373598,"lng":140.16935426,"geo_status":"db","era":"明治41頃","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造、鉄板葺、延長5.6m","structure_material":"木造","registered":"2003.09.19(平成15.09.19)","register_no":"09 － 0080","desc":"文庫蔵と主屋背面の突出部を矩ね折れに繋ぎ，奥座敷前の中庭を囲う。緩い勾配の屋根を架け，引違戸を建てた腕木門を南方に開き，前後は上部に連子，下部に菱子を入れて透かした屋根付き板塀で緩やかに仕切る。邸内内向き部分の構えに欠くことのできない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003509"},{"id":"00003508","register_sub_id":"101","register_pk":"104498","name":"飯塚家住宅新宅文庫蔵","kana":"いいづかけじゅうたくしんたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県那須郡那珂川町馬頭字南町360","lat":36.73744377,"lng":140.16934777,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、銅板葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"09 － 0079","desc":"主屋のすぐ裏に建つ。２階建，土蔵造，切妻造，妻入，桟瓦葺で，南面戸口に庇を付ける。両側面に半間毎に柱を立て，これと等間隔に配された大引，登梁とで架構を組み，登梁頂部は地棟で受ける。外部は庇柱，桁，繋梁も漆喰で塗込めた丁寧で堅牢な造りとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003508"},{"id":"00003514","register_sub_id":"101","register_pk":"104504","name":"飯塚家住宅本宅表門","kana":"いいづかけじゅうたくほんたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県那須郡那珂川町馬頭363-1","lat":36.73720579,"lng":140.16974016,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.9m","structure_material":"木造","registered":"2003.09.19(平成15.09.19)","register_no":"09 － 0085","desc":"離れの南東に表通りに面して建つ。切妻造，桟瓦葺，大型の棟門形式で，本柱背後に控え柱を立て固める。屋根の照りや軒反りはなく棟積みも低いなど全体に簡素な外観だが，吟味された良材を用い，通りからやや控えて建ち正面に溜まりを取るなど，格式を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003514"},{"id":"00003513","register_sub_id":"101","register_pk":"104503","name":"飯塚家住宅本宅離れ","kana":"いいづかけじゅうたくほんたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県那須郡那珂川町馬頭363-1","lat":36.73732714,"lng":140.16957605,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"09 － 0084","desc":"離れの南東に表通りに面して建つ。切妻造，桟瓦葺，大型の棟門形式で，本柱背後に控え柱を立て固める。屋根の照りや軒反りはなく棟積みも低いなど全体に簡素な外観だが，吟味された良材を用い，通りからやや控えて建ち正面に溜まりを取るなど，格式を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003513"},{"id":"00003515","register_sub_id":"101","register_pk":"104505","name":"飯塚家住宅本宅脇門","kana":"いいづかけじゅうたくほんたくわきもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県那須郡那珂川町馬頭363-1","lat":36.73725489,"lng":140.16975198,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、鉄板葺、間口1.8m、袖塀付","structure_material":"木造","registered":"2003.09.19(平成15.09.19)","register_no":"09 － 0086","desc":"表門に直交し敷地を東西に仕切る位置に建つ。切妻造，銅板葺の棟門形式で，本柱西側に控え柱を立て，門の南に長１間の袖板塀を付属する。簡素な門だが屋根に強い起りを付け，戸口に粗い組子の引違格子戸を建てるなど瀟洒な意匠で，邸内内向きの一角を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003515"},{"id":"00002212","register_sub_id":"101","register_pk":"103202","name":"イタリア大使館別荘記念公園本邸","kana":"いたりあたいしかんべっそうきねんこうえんほんてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"栃木県","address":"栃木県日光市中宮祠2482","lat":36.72539719,"lng":139.48516911,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積379㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"09 － 0052","desc":"日光中禅寺湖畔に建つレーモンド設計の別荘建築。居間，書斎，食堂を１室とし，湖を臨む西面にサンルーム風ベランダを設け，２階に寝室４室を配する。コンパクトなプランニングとともに，杉皮と杉板を割竹で押さえた，類例の無い内外装意匠に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002212"},{"id":"00004913","register_sub_id":"101","register_pk":"105903","name":"雨情茶屋離れ（野口雨情旧居）","kana":"うじょうちゃやはなれ（のぐちうじょうきゅうきょ）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県宇都宮市鶴田町字長峰1744-28","lat":36.56290969,"lng":139.84690021,"geo_status":"db","era":"昭和5頃／平成12移築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0121","desc":"県道宇都宮・鹿沼線沿いに北面して建つ。桁行６間，梁間４間規模，入母屋造，桟瓦葺の木造平屋で，外壁を下見板張とする。居室４室と台所，浴室を配する昭和初期の住宅建築で，童謡詩人・野口雨情の終焉の住まいで，「雨情旧居」として地域に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004913"},{"id":"00005244","register_sub_id":"101","register_pk":"106232","name":"生沼家住宅店舗及び主屋","kana":"おいぬまけじゅうたくてんぽおよびしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県河内郡上三川町大字上三川4978-1","lat":36.4352,"lng":139.912781,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積187㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0139","desc":"町中心部の角地に建つ商家。桁行，梁間とも７間半とし，切妻造，平入の南北棟の北端に，東西棟の入母屋造の２階部を載せた特異な構造。平側を出桁造とし，黒漆喰仕上の南妻には大型の窓を開き，銅板葺の庇を付ける。角地の街路景観を形成し際立った存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005244"},{"id":"00005245","register_sub_id":"101","register_pk":"106233","name":"生沼家住宅土蔵","kana":"おいぬまけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県河内郡上三川町大字上三川4978-1","lat":36.43527526,"lng":139.91277995,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"09 － 0140","desc":"店舗及び主屋の北側に接続する文庫蔵。桁行５．２ｍ，梁間４．３ｍの切妻造，平入で，２階は街路側窓に掛子塗り戸を設ける。１階の外壁は目地付のモルタル塗洗出しとし，２階の鉢巻及び壁面は黒漆喰で仕上げ，腰を海鼠壁風とする独特な外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005245"},{"id":"00003194","register_sub_id":"101","register_pk":"104184","name":"大川家住宅大門","kana":"おおかわけじゅうたくおおもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市小俣町1412","lat":36.383102,"lng":139.37085,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2.9m","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"09 － 0077","desc":"主屋の南方，旧納屋の西方に位置し，大門橋から続く道路からは東側に振れて建つ。１間１戸の薬医門で，両脇に潜戸を開け，両側に腰を下見板張とした漆喰塗袖塀を廻す。本柱間及び控柱間に架け渡した木太い冠木が格式を示す。屋敷構に欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003194"},{"id":"00003191","register_sub_id":"101","register_pk":"104181","name":"大川家住宅旧納屋","kana":"おおかわけじゅうたくきゅうなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市小俣町1412","lat":36.383068,"lng":139.370926,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積77㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"09 － 0074","desc":"屋敷地の東南隅に東西棟で建つ。桁行５間梁間３間規模，桟瓦葺，切妻造の木造２階建で，東端部は敷地形状に対応した台形平面の下屋を差掛けて納める。外部は西・南・東の三面を押縁下見板張として屋敷景観を整えている。屋敷地東方便益部の主要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003191"},{"id":"00003188","register_sub_id":"101","register_pk":"104178","name":"大川家住宅主屋","kana":"おおかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市小俣町1412","lat":36.383282,"lng":139.370941,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積317㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"09 － 0071","desc":"北に山を控えた高台に位置する屋敷地の中央に東西棟で建つ。桁行１０間半梁間４間半，桟瓦葺，切妻屋根のたちの高いセガイ造り２階建で，背面に梁間３間の一部に中庭を設けた下屋が付く。西方を上手として式台玄関を設け，下手の東３間半分を機場としていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003188"},{"id":"00003192","register_sub_id":"101","register_pk":"104182","name":"大川家住宅巽蔵","kana":"おおかわけじゅうたくたつみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市小俣町1412","lat":36.383106,"lng":139.371002,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"09 － 0075","desc":"旧納屋東端下屋部の北方に南北棟で建つ。桁行４間梁間３間規模の２階建土蔵で，庭側の西面に土庇を差掛けて蔵前をとる。屋根は桟瓦葺，切妻造の置屋根とし，外壁は白漆喰塗に仕上げる。続蔵とともに屋敷地東辺の石垣上に建ち，屋敷地東面の景観の中核をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003192"},{"id":"00003193","register_sub_id":"101","register_pk":"104183","name":"大川家住宅続蔵","kana":"おおかわけじゅうたくつづきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県足利市小俣町1412","lat":36.383221,"lng":139.371048,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造及び土蔵造平屋建、瓦葺、建築面積81㎡","structure_material":"木造及び土蔵造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"09 － 0076","desc":"主屋の東方に位置し，巽蔵の北に連なる。桁行３間梁間３間の物置としての巽屋，桁行２間梁間２間の穀蔵，桁行３間梁間２間の味噌蔵から成り，「建てぐるみ」式に桟瓦葺の切妻屋根を一体的に架ける。東面は押縁下見板張として白漆喰塗の巽蔵と対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003193"},{"id":"00003190","register_sub_id":"101","register_pk":"104180","name":"大川家住宅西蔵","kana":"おおかわけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市小俣町1412","lat":36.383335,"lng":139.370636,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"09 － 0073","desc":"主屋の西方，本蔵の南西に南北棟で建つ。本蔵とは壁沿いの渡廊下で連絡され，北妻面に入口を設ける。桁行３間梁間２間規模の妻入２階建土蔵で，屋根は桟瓦葺，切妻造の置屋根とし，外壁は白漆喰仕上げとする。本蔵とともに屋敷地西方の主要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003190"},{"id":"00003189","register_sub_id":"101","register_pk":"104179","name":"大川家住宅本蔵","kana":"おおかわけじゅうたくほんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県足利市小俣町1412","lat":36.38343,"lng":139.370712,"geo_status":"db","era":"嘉永4","year":1851,"year_source":"db","year_min":1851,"year_max":1851,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"09 － 0072","desc":"主屋北西隅の納戸の西方に２階建の蔵前を介して南北棟で建つ。桁行６間梁間２間半の細長平面をもつ平入の２階建土蔵で，屋根は桟瓦葺，切妻造の置屋根とし，外壁は腰を黒漆喰，上部を白漆喰に仕上げる。質蔵として建てられ，貼紙から建設年代が知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003189"},{"id":"00001873","register_sub_id":"101","register_pk":"102863","name":"岡田家住宅翁島別邸主屋","kana":"おかだけじゅうたくおきなじまべっていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県栃木市小平町1-23","lat":36.386051,"lng":139.732254,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積186㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0027","desc":"岡田家は江戸初期以来の旧家で，旧栃木宿の西北口に位置する。別邸は旧例幣使街道と巴波川に囲まれた地に広大な屋敷地を構えている。主屋は大正１３年に隠居所として建てられ，Ｌ字型平面の一部２階建・桟瓦葺で，銘木を用い，上質の数寄屋風意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001873"},{"id":"00001874","register_sub_id":"101","register_pk":"102864","name":"岡田家住宅翁島別邸土蔵","kana":"おかだけじゅうたくおきなじまべっていどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県栃木市小平町1-23","lat":36.386127,"lng":139.732147,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0028","desc":"岡田家は代々嘉右衛門を襲名し，嘉右衛門町の地名もこれに由来する。土蔵は主屋の北西に隣接して建ち，寄棟造・桟瓦葺，総２階建である。規模は桁行３間・梁間２間半と大きくないが，高い切石積の基礎や，円弧付の蛇腹軒など，丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001874"},{"id":"00006559","register_sub_id":"101","register_pk":"107542","name":"小川家住宅表門","kana":"おがわけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県小山市乙女3-10-34","lat":36.26091818,"lng":139.76081999,"geo_status":"db","era":"明治45頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"石造、瓦葺、間口7.3m、袖塀付","structure_material":"石造","registered":"2007.07.31(平成19.07.31)","register_no":"09 － 0169","desc":"国道沿いの敷地北辺中央に建ち，折曲り１０ｍの築地塀中央に門口を開く。モルタル仕上げ，桟瓦葺。門口は御影石で門構えをつくり，板戸を建てる。隅部の隅石，妻部の洋風彫刻，繰形付の軒蛇腹などに洋風意匠を採り入れた上質な表門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006559"},{"id":"00006557","register_sub_id":"101","register_pk":"107540","name":"小川家住宅米蔵","kana":"おがわけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県小山市乙女3-10-34","lat":36.260635,"lng":139.760986,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造平屋一部2階建、瓦葺、建築面積198㎡","structure_material":"土蔵造平屋一部2階建","registered":"2007.07.31(平成19.07.31)","register_no":"09 － 0167","desc":"敷地西辺の県道沿いに建つ。桁行１５間，梁間４間半，前面に奥行１間の庇付，土蔵造平屋一部２階建，寄棟造，桟瓦葺。外壁は漆喰塗で，内部は５室に間仕切られ，各々に大戸口と背面に採光窓を開く。小屋はキングポストトラス。当家の繁栄を伝える長大な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006557"},{"id":"00006555","register_sub_id":"101","register_pk":"107538","name":"小川家住宅主屋","kana":"おがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県小山市乙女3-10-34","lat":36.260899,"lng":139.761078,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積195㎡","structure_material":"木造2階一部平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"09 － 0165","desc":"敷地中程に建ち，建築面積１９５㎡，木造２階一部平屋建，桟瓦葺。外壁は下見板張で，側廻りに開口部を広くとる。内部は和室を基本とし，２階洋室は華麗な漆喰彫刻で装飾する。南西妻には大きな入母屋破風を見せ，豪商の居宅に相応しい，堂々とした外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006555"},{"id":"00006556","register_sub_id":"101","register_pk":"107539","name":"小川家住宅土蔵","kana":"おがわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県小山市乙女3-10-34","lat":36.26102711,"lng":139.76095968,"geo_status":"db","era":"明治27／明治44移築","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"09 － 0166","desc":"主屋前面に建つ。桁行５間半，梁間２間半及び２間とし，土蔵造２階建，切妻造，桟瓦葺。開口部廻りの漆喰塗，屋根鬼瓦の漆喰影盛，内部造作などいずれも上質。小川家が繁栄の礎を築いた乙女河岸から移築され，舟運で栄えた商家の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006556"},{"id":"00006558","register_sub_id":"101","register_pk":"107541","name":"小川家住宅肥料蔵","kana":"おがわけじゅうたくひりょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県小山市乙女3-10-34","lat":36.260696,"lng":139.761139,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"土蔵造2階一部平屋建、瓦葺、建築面積111㎡","structure_material":"土蔵造2階一部平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"09 － 0168","desc":"主屋後方に建つ。桁行８間，梁間３間，背面に桁行６間半，梁間１間半の下屋を付ける。土蔵造２階一部平屋建，寄棟造，小屋組はキングポストトラス，桟瓦葺。内部は３室に区画され，各室の正面に大戸口を開く。主商品である肥料を保管していた土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006558"},{"id":"00005556","register_sub_id":"101","register_pk":"106544","name":"荻野家住宅内蔵","kana":"おぎのけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市通3-3545","lat":36.33472261,"lng":139.44772792,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積71㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"09 － 0142","desc":"主屋の西方に位置し，南北棟で建つ。桁行４間，梁間２間半規模，切妻造，桟瓦葺の２階建土蔵で，東面に戸口を設け，１階南面と２階南北両面に窓を開ける。地棟の墨書から年代と「棟梁小林利助」が判明する。階段の側桁に繰形装飾を施すなど丁寧なつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005556"},{"id":"00005557","register_sub_id":"101","register_pk":"106545","name":"荻野家住宅表門","kana":"おぎのけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市通3-3545","lat":36.33479642,"lng":139.44789602,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口1.9m、板塀延長15m付","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"09 － 0143","desc":"主屋の玄関前に対応し，敷地北辺の東寄りに北側旧街道からやや退いて東西棟で建つ。切妻造，桟瓦葺，１間１戸の腕木門で，主柱間は１．９ｍとし，内開きの縦板張戸を吊り込み，背面に控柱を建てる。簡素な門であるが，旧街道沿いの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005557"},{"id":"00005555","register_sub_id":"101","register_pk":"106543","name":"荻野家住宅主屋","kana":"おぎのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市通3-3545","lat":36.33469777,"lng":139.44781109,"geo_status":"db","era":"明治25／大正初期増築","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積180㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"09 － 0141","desc":"旧街道に北面する敷地の北寄りに建つ。主体部は桁行４間半，梁行５間規模，寄棟造，桟瓦葺の木造２階建で，西方内蔵との間に蔵前を設け，北西方に台所部を増築する。２階南西部を客座敷とし，蔵前上部に茶室を配する。有力商家の住宅の有り様を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005555"},{"id":"00005558","register_sub_id":"101","register_pk":"106546","name":"荻野家住宅南塀","kana":"おぎのけじゅうたくみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和中","pref":"栃木県","address":"栃木県足利市通3-3545","lat":36.33446543,"lng":139.44773406,"geo_status":"db","era":"昭和25頃","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造、鉄板葺、延長21m","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"09 － 0144","desc":"敷地南側を東西に走る両毛線の線路敷との境に建つ。木造，縦板目板張，鉄板葺の塀で，柱間１．３ｍの２５間規模に造り，庭側に２間または３間毎に控えをとる。高さ２．４ｍで，欄間に横組子１本を入れる。屋敷地南面の景観を整える要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005558"},{"id":"00008637","register_sub_id":"101","register_pk":"149358","name":"小根澤家長屋西棟","kana":"おねざわけながやにしむね","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市入舟町2-15","lat":36.381715,"lng":139.72874094,"geo_status":"db","era":"明治6年／明治後期移築・昭和40年頃改修","year":1873,"year_source":"converted","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0191","desc":"県官舎として建てられた住宅。寄棟造平屋建で桁行18ｍ梁間7.3ｍ。中央南に寄棟造屋根を突出し水まわりとする。左右対称の平面になる2軒で、それぞれ生活と接客との動線を玄関から分け、座敷にトコを設える。小規模で簡素ながら、独特の雰囲気を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008637"},{"id":"00008636","register_sub_id":"101","register_pk":"149357","name":"小根澤家長屋東棟","kana":"おねざわけながやひがしむね","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県栃木市入舟町2-15","lat":36.38172224,"lng":139.72896406,"geo_status":"db","era":"明治6年／明治後期移築・平成9年改修","year":1873,"year_source":"converted","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0190","desc":"栃木県官舎として建てられた住宅。桁行16ｍ梁間7.3ｍの木造平屋建。東西棟の西寄棟造とする桟瓦葺。2棟からなる長屋で、各戸の中央に玄関を置き、和室4室と台所を配する。明治初期に建設された地方官舎の歴史を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008636"},{"id":"00005740","register_sub_id":"101","register_pk":"106728","name":"小野口家住宅石塀","kana":"おのぐちけじゅうたくいしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県宇都宮市田野町885","lat":36.5988285,"lng":139.7974448,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"石造、延長174m","structure_material":"石造","registered":"2006.10.18(平成18.10.18)","register_no":"09 － 0152","desc":"長屋門，旧乾燥小屋，堆肥舎及び旧酒蔵を繋ぎ，屋敷地の南辺以外をほぼ囲う。総延長１７４ｍで，大谷石積とし基礎に４段の切石を積み，笠石を載せる。特に西辺は，最上段に逆凹形の切石を用いて小窓を並べ，意匠的な工夫をみせ，正面の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005740"},{"id":"00001342","register_sub_id":"101","register_pk":"102332","name":"小野口家住宅裏の蔵","kana":"おのぐちけじゅうたくうらのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県宇都宮市田野町885","lat":36.59883873,"lng":139.79756522,"geo_status":"db","era":"文政8","year":1825,"year_source":"db","year_min":1825,"year_max":1825,"year_label":null,"structure":"石造2階建、瓦葺、建築面積22㎡","structure_material":"石造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"09 － 0018","desc":"主屋の北東後方に建ち，食器具等の倉庫として用いられている。墨書より文政８年と判明し，小野口家のなかで建築年代が最も古い。もと石屋根，軸組木造，外壁大谷石の薄板貼で，戸口には，かつての主屋車寄の唐破風庇を移設している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001342"},{"id":"00001340","register_sub_id":"101","register_pk":"102330","name":"小野口家住宅旧乾燥小屋","kana":"おのぐちけじゅうたくきゅうかんそうごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県宇都宮市田野町885","lat":36.598568,"lng":139.797577,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"石造平屋建、瓦葺、建築面積37㎡","structure_material":"石造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"09 － 0016","desc":"屋敷地南西面で長屋門北側にあり，長屋門を移動した大正中期の建築。もと葉煙草の乾燥に使われていた。大谷石積みの平屋建てで，主屋に面した敷地内側に収納のための開口部がある。長屋門に接続する倉庫建築として，屋敷構えの景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001340"},{"id":"00001343","register_sub_id":"101","register_pk":"102333","name":"小野口家住宅旧酒蔵","kana":"おのぐちけじゅうたくきゅうさかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県宇都宮市田野町885","lat":36.59896634,"lng":139.79762673,"geo_status":"db","era":"明治5","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造平屋建、亜鉛メッキ鋼板葺、建築面積115㎡","structure_material":"土蔵造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"09 － 0019","desc":"主屋の後方，屋敷地最北に建ち，かつては酒蔵に用いられていた。墨書より明治５年の建築。長屋門などと同じく，軸組木造，外壁大谷石の薄板貼である。腰部に廻した水切りの段と上部の隅縦石貼により，単調になりがちな外観を端正にまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001343"},{"id":"00001341","register_sub_id":"101","register_pk":"102331","name":"小野口家住宅堆肥舎","kana":"おのぐちけじゅうたくたいひしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県宇都宮市田野町885","lat":36.598686,"lng":139.79747,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造平屋建、瓦葺、建築面積41㎡","structure_material":"石造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"09 － 0017","desc":"長屋門北面に連続する旧乾燥小屋と通路を挟んだ北側に建ち，明治後期と推定されている。大谷石積みの平屋建であるが，寄棟造の屋根はトラス小屋組である。開口部に付けられた大谷石の付庇，松文型の窓，隅部の石積みなどに造形上の工夫がうかがえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001341"},{"id":"00001339","register_sub_id":"101","register_pk":"102329","name":"小野口家住宅長屋門","kana":"おのぐちけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県宇都宮市田野町885","lat":36.598495,"lng":139.797623,"geo_status":"db","era":"明治9／大正期移築","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積70㎡","structure_material":"石造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"09 － 0014","desc":"小野口家は江戸時代より長く庄屋をつとめ，当地方の豪農の屋敷構えを保っている。屋敷地南西面に建つ長屋門は，墨書より明治９年の建築。もと石屋根，木造軸組に外壁大谷石貼り，木製アーチ状出入口やアーチ式小窓など洋風を取り入れた意匠に見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001339"},{"id":"00001338","register_sub_id":"101","register_pk":"102328","name":"小野口家住宅前の蔵","kana":"おのぐちけじゅうたくまえのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県宇都宮市田野町885","lat":36.59857278,"lng":139.79813767,"geo_status":"db","era":"江戸時代末期／明治末期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"石造2階建、瓦葺、建築面積20㎡","structure_material":"石造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"09 － 0015","desc":"小野口家は広大な屋敷地中央に近年新築した主屋が建ち，これを囲むよう各建築群が配されている。前の蔵は敷地南東隅にあり，軸組を木造とし，外壁には田下石（大谷石の一種）の薄板を貼り付け，軒を蛇腹型に持ち出し，もとは大谷石の石屋根であった。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001338"},{"id":"00009895","register_sub_id":"101","register_pk":"196042","name":"金谷侍屋敷主屋（旧金谷カッテージイン主屋）","kana":"かなやさむらいやしきしゅおく（きゅうかなやかってーじいんしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県日光市本町2249他","lat":36.75421166,"lng":139.59280941,"geo_status":"db","era":"江戸後期／明治6・明治18・昭和中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、鉄板葺、建築面積191㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"09 － 0212","desc":"日光山内の西側に位置する。南正面の東寄りに玄関を構え、板敷のいろりの間を中心に座敷等を配する。明治六年に外国人旅行者の宿泊施設とするため一部改修し、同一八年に西側に二階建の客室棟を増築した。わが国最初期の外国人専用宿泊施設として希少な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009895"},{"id":"00009896","register_sub_id":"101","register_pk":"196043","name":"金谷侍屋敷土蔵（旧金谷カッテージイン土蔵）","kana":"かなやさむらいやしきどぞう（きゅうかなやかってーじいんどぞう）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県日光市本町2249他","lat":36.75421978,"lng":139.59293384,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、鉄板葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"09 － 0213","desc":"主屋の東側に位置する、桁行四・七メートル梁間三・七メートル、置屋根形式の二階建土蔵。外壁は漆喰塗で鉢巻を廻し、腰に長方形の石を張り漆喰目地で押さえる。柱や内壁にはクリ材を用いて仕上げる。観光地の一郭において、当地の歴史的景観を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009896"},{"id":"00004521","register_sub_id":"101","register_pk":"105511","name":"巖華園表門","kana":"がんかえんおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市月谷町8","lat":36.36151338,"lng":139.46468314,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口5.5m、塀延長18m付","structure_material":"木造","registered":"2005.02.09(平成17.02.09)","register_no":"09 － 0119","desc":"宅地の東辺中央に位置する。間口１８尺規模の腕木門で，屋根は切妻造，桟瓦葺とする。中央の９尺に両開の門扉を釣り込み，脇間は白漆喰壁で腰を簓子下見板張とする。控壁と脇塀は木造瓦葺で，腰を下見板張とする。脇塀は南北に延び，南では旧馬屋に接続する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004521"},{"id":"00004516","register_sub_id":"101","register_pk":"105506","name":"巖華園蔵","kana":"がんかえんくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市月谷町8","lat":36.36145876,"lng":139.46422276,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"09 － 0114","desc":"主屋の西方，宅地西端に位置する。桁行３間梁間２間の土蔵造２階建で，南北棟，切妻造の置屋根を桟瓦葺とする。外壁白漆喰塗で，東面中央に戸口を開ける。現在は１階１室，２階２室の客室とし，１階の四周に下屋庇を付け，２階東面と南面の窓を改修している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004516"},{"id":"00004519","register_sub_id":"101","register_pk":"105509","name":"巖華園倶楽部（旧馬屋）","kana":"がんかえんくらぶ（きゅううまや）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県足利市月谷町8","lat":36.361382,"lng":139.464691,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"09 － 0117","desc":"旧外蔵北妻の蔵前から北へ接続する。桁行５間半梁間１間半の木造平屋建で，屋根は切妻造，桟瓦葺の南北棟。外壁は真壁造の白漆喰塗で，腰を押縁下見板張とする。東面には高窓を開く。内部は小屋組を見せた土間床の接客室としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004519"},{"id":"00004520","register_sub_id":"101","register_pk":"105510","name":"巖華園ゲストハウス（旧書院）","kana":"がんかえんげすとはうす（きゅうしょいん）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市月谷町8","lat":36.36167752,"lng":139.46452228,"geo_status":"db","era":"明治中期／昭和20頃移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"09 － 0118","desc":"主屋の北方に位置する。もとは主屋の西背面南寄りに接続した。桁行５間梁間３間の木造平屋建で，移築時に桁行を縮めている。屋根は寄棟造，桟瓦葺で，外壁は真壁造の白漆喰塗。内部は，座敷８畳と次の間６畳に縁を廻す。玄関，洋間と水回りは移築時の改修。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004520"},{"id":"00004518","register_sub_id":"101","register_pk":"105508","name":"巖華園好時亭（旧外蔵）","kana":"がんかえんこうじてい（きゅうそとぐら）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"栃木県","address":"栃木県足利市月谷町8","lat":36.36129404,"lng":139.46469028,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"09 － 0116","desc":"宅地の東辺南端に位置する。桁行４間梁間２間半の２階建土蔵で，切妻造の置屋根を桟瓦葺とする南北棟である。外壁は漆喰塗，東面腰を下見板張とする。北妻に蔵前を設けて戸口を開く。西面１，２階と東面２階に各２箇所の窓を開き，内部は畳敷の客室とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004518"},{"id":"00004515","register_sub_id":"101","register_pk":"105505","name":"巖華園主屋","kana":"がんかえんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県足利市月谷町8","lat":36.36150011,"lng":139.46444152,"geo_status":"db","era":"江戸末期／昭和初期・昭和20代増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積312㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"09 － 0113","desc":"宅地の中央に東面して建つ。北半を土間とした大規模な四間取農家で，昭和初期までに２階を増築，玄関式台を整備した。屋根は切妻造，桟瓦葺で庇が巡る。土間は厨房に改修した。２階には和室３室と洋室２室がある。西面南端の和室２室は昭和２０年代の増築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004515"},{"id":"00004517","register_sub_id":"101","register_pk":"105507","name":"巖華園新蔵","kana":"がんかえんしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県足利市月谷町8","lat":36.3615958,"lng":139.46425852,"geo_status":"db","era":"文久2","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"09 － 0115","desc":"主屋の西，蔵の北に位置する。桁行４間半梁間２間半の土蔵造２階建で，切妻造の置屋根を桟瓦葺とし，外壁は白漆喰塗で，腰を黒漆喰塗とする。南面西寄りに戸口を設け，両開の漆喰塗戸を釣り，２階の南面と東面に窓を開く。建設年代は小屋束の墨書による。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004517"},{"id":"00013503","register_sub_id":"101","register_pk":"504867","name":"旧岡崎家住宅石蔵","kana":"きゅうおかざきけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市通三丁目2763","lat":36.33544722,"lng":139.44759722,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石造2階建、瓦葺、建築面積53㎡","structure_material":"石造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"09 － 0254","desc":"隠居屋の北に東面して建つ。石造二階建切妻造桟瓦葺。南北棟で戸口を建てる東面に下屋を差掛ける。大谷石を化粧とし地域の石蔵の特色を示す。小屋組はキングポストトラス。内部は一、二階とも一室で生糸や家財道具等を収納。足利の織物産業の隆盛を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013503"},{"id":"00013502","register_sub_id":"101","register_pk":"504866","name":"旧岡崎家住宅隠居屋","kana":"きゅうおかざきけじゅうたくいんきょや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"栃木県","address":"栃木県足利市通三丁目2763","lat":36.33532222,"lng":139.44753333,"geo_status":"db","era":"昭和11年／平成9年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積111㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"09 － 0253","desc":"足利市を横断する旧国道五〇号沿いに位置。設計施工は市内で実績多数の小川組。二階建入母屋造桟瓦葺で南の一、二階を和室として縁を廻らし、北に廊下をはさんで洋室を配する。縁廻りはガラス戸を建て並べ、洋室には暖炉を設えるなど質の高い近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013502"},{"id":"00013504","register_sub_id":"101","register_pk":"504868","name":"旧山中家住宅主屋（民俗資料館夜明け前）","kana":"きゅうやまなかけじゅうたくおもや（みんぞくしりょうかんよあけまえ）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県下野市国分寺字新開820-1","lat":36.38359167,"lng":139.80847778,"geo_status":"db","era":"江戸末期／平成7年移築、平成29年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（銅板仮葺）、建築面積191㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"09 － 0255","desc":"下野市小金井に所在したが市に寄贈され公園に移築。東西棟の直屋で平屋建寄棟造。屋根は茅葺で銅板で仮葺する。土間が広く、床上部は二列六室に縁を廻らす大規模なもの。土間上部の二重梁などは見応えがある。市内に残る近世に遡る農家建築として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013504"},{"id":"00014734","register_sub_id":"101","register_pk":"518992","name":"饗茶庵花蓮店舗（旧安生家住宅主屋）","kana":"きょうちゃあんはなれてんぽ（きゅうあんじょうけじゅうたくおもや）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県鹿沼市上材木町1686-1","lat":36.56831944,"lng":139.74564444,"geo_status":"db","era":"大正5年／昭和37年増築、令和2年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積76㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"09 - 0272","desc":"鹿沼城跡北東に位置する和洋折衷の住宅主屋。敷地中央に東面する寄棟造瓦棒鉄板葺。正面に切妻造玄関を付し、北に洋室、南に床構え付き座敷を配して縁を廻らす。洋室外壁はモルタル塗仕上で目地を切り石造風にみせ、端正な外観が地域の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014734"},{"id":"00003800","register_sub_id":"101","register_pk":"104790","name":"櫻井肥料店主屋","kana":"さくらいひりょうてんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市万町15-17","lat":36.384071,"lng":139.734695,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0103","desc":"店舗ミセ部分の西側に接して東西棟で建つ。桁行５間梁間５間半規模，切妻造，桟瓦葺の平屋建で，南半に玄関・台所，北方に８畳半の主人室・８畳座敷を配し，台所の西方に便所・浴室を，西北方に６畳の奥座敷を突き出す。栃木町の大店の居住空間を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003800"},{"id":"00003801","register_sub_id":"101","register_pk":"104791","name":"櫻井肥料店文庫蔵","kana":"さくらいひりょうてんぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市万町15-17","lat":36.38410653,"lng":139.7344903,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0104","desc":"主屋の西方に位置し，東西棟で建つ。桁行５間梁間２間半規模，切妻造，桟瓦葺，平入の２階建土蔵で，南面に庇を差し掛けて西寄りに戸口を設ける。南面１階２階の開口部扉はいずれも漆喰塗の防火引戸とし，通り沿いの北面は腰を簓子下見張として景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003801"},{"id":"00010913","register_sub_id":"101","register_pk":"208884","name":"篠原家住宅石蔵","kana":"しのはらけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県日光市稲荷町一丁目393-2","lat":36.749234,"lng":139.615101,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"石造2階建、鉄板葺、建築面積25㎡","structure_material":"石造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"09-0220","desc":"敷地の南西隅に東面して建つ。大谷石を組んで造られた二階建の蔵で、正面出入口上部はアーチとする。小屋はキングポストトラスで、庇には曲線の幾何意匠の持送金物を付けるなど、部分的に洋風意匠となる。軒蛇腹なども大谷石で作り出し、高い技術を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010913"},{"id":"00010912","register_sub_id":"101","register_pk":"208883","name":"篠原家住宅主屋","kana":"しのはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県日光市稲荷町一丁目393-2","lat":36.749358,"lng":139.615238,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"09-0219","desc":"日光駅にほど近い住宅街に敷地を構える。主屋は南北棟の入母屋造とし、東面北端に入母屋造の玄関を張り出す。玄関の先には洋風内装の応接室を、背面に茶の間や水回りを配し、中廊下を介して南に田字の座敷を設ける。当地の上質な近代和風住宅の様相を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010912"},{"id":"00011256","register_sub_id":"101","register_pk":"209091","name":"島田家住宅主屋","kana":"しまだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県佐野市田島町488","lat":36.298496,"lng":139.565247,"geo_status":"db","era":"江戸末期／明治中期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積274㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"09－0224","desc":"島田家は、佐野市南西方で酒造業を営む商家。主屋は南面して建つ。右土間で、床上部は東から三室、二室、二室を並べ、南西室には座敷飾を設ける。式台玄関を備え、二階にも雁行状に座敷を並べ、接客を意識した建物である。蔵元の華やかな生活様態を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011256"},{"id":"00001883","register_sub_id":"101","register_pk":"102873","name":"関根家住宅主屋","kana":"せきねけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町11-4","lat":36.37897742,"lng":139.73376262,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積106㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0037","desc":"主屋は店舗背面に平屋建部が連続して建ち，敷地奥に延びて２階建部がある。南側の通り土間が店舗土間と連絡している。真壁造，桟瓦葺，奥は１・２階とも床・棚付の座敷で，数寄屋風の繊細な意匠で纏まっている。敷地奥の居住空間の様相が伺える実例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001883"},{"id":"00001884","register_sub_id":"101","register_pk":"102874","name":"関根家住宅文庫蔵","kana":"せきねけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県栃木市倭町11-4","lat":36.37897414,"lng":139.73392724,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積66㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0038","desc":"主屋後方に中庭を挟んで建つ土蔵で，もとは東側に土蔵が２棟続いていた。江戸末期の建設と伝える。東西棟の切妻造・桟瓦葺，２階建で，東面の主屋側と南側に庇を付ける。１階は壁面に収蔵棚を設け，２階は畳敷で南面に窓を設け，書斎兼座敷風に扱っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001884"},{"id":"00003795","register_sub_id":"101","register_pk":"104785","name":"舘野家住宅主屋","kana":"たてのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県栃木市泉町2-32","lat":36.38453971,"lng":139.73414188,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階一部平屋建、瓦葺及び鉄板葺、建築面積97㎡","structure_material":"木造2階一部平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"09 － 0098","desc":"店舗西方背後に位置し，桁行５間梁間３間規模，東西棟，寄棟造，桟瓦葺の木造２階建と，店舗西面に沿った平屋建とから成る。１階は１０畳座敷・６畳・８畳をＬ字型に配し，８畳の南を台所や浴室などに充てる。全体は和風であるが，西南端部は腰を石積とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003795"},{"id":"00010098","register_sub_id":"101","register_pk":"197931","name":"田波家住宅主屋","kana":"たなみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県小山市大字南小林74-1","lat":36.322595,"lng":139.739514,"geo_status":"db","era":"江戸末期／明治前期・大正15・昭和53改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積185㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"09 － 0216","desc":"巴波川沿いの田園地帯に位置する敷地のほぼ中央に南面して建つ。桁行一二間半、梁間四間の寄棟造で、床上部を六間取系平面とし、表側に八畳を三室並べ、土間境室に式台を構える。主室は付書院を備え、トコの痕跡を持つ。北関東における大型民家建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010098"},{"id":"00010099","register_sub_id":"101","register_pk":"197932","name":"田波家住宅離れ","kana":"たなみけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県小山市大字南小林74-1","lat":36.322595,"lng":139.739514,"geo_status":"db","era":"江戸末期／昭和23頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"09 － 0217","desc":"主屋の南西側に廊下を介して建ち、東正面に式台を構える。内部は式台から廊下を隔てて八畳の座敷二室を東西に並べ、南側に幅一間の入側、西側に幅半間の縁側を設ける。トコ・棚・付書院を設え、長押を廻し、釘隠を打つなど、格式を備えた接客施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010099"},{"id":"00005563","register_sub_id":"101","register_pk":"106551","name":"田沼家住宅稲荷社","kana":"たぬまけじゅうたくいなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県足利市島田町409","lat":36.29976269,"lng":139.44336773,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.8㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"09 － 0149","desc":"屋敷地の北西隅部，土蔵の西側に南面して建つ。洗い出し仕上げの台座に載る入母屋造，銅板葺の覆屋の内部に流造の１間社を安置する。覆屋は欅材で造られ，正面桁行１．２ｍ，梁間１．５ｍ規模である。棟札から棟梁穐山兼吉が判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005563"},{"id":"00005561","register_sub_id":"101","register_pk":"106549","name":"田沼家住宅表門","kana":"たぬまけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市島田町409","lat":36.29978007,"lng":139.44371551,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"09 － 0147","desc":"主屋の北東方，屋敷地の北辺ほぼ中央に，旧例幣使街道からかなり退いて建つ。切妻造，桟瓦葺，木造の１間１戸薬医門で，柱間３ｍの規模。東西に袖塀を従え，さらに矩折に街道に向けて塀を延ばして門前を囲い，街道から石畳を敷いて風格ある門構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005561"},{"id":"00005559","register_sub_id":"101","register_pk":"106547","name":"田沼家住宅主屋","kana":"たぬまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県足利市島田町409","lat":36.29958623,"lng":139.44353459,"geo_status":"db","era":"江戸中期／明治27頃増改造","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋一部2階建、瓦葺、建築面積233㎡","structure_material":"木造平屋一部2階建","registered":"2006.08.03(平成18.08.03)","register_no":"09 － 0145","desc":"旧例幣使街道に北面する屋敷地の北西寄りに南面して建つ。桁行９間半，梁間４間，切妻造，桟瓦葺で，北方に台所等を角屋で出し，東面に入母屋造の車寄を付ける。内部は東に土間をとり，西を六間取とする。もと寄棟造，茅葺。現在は明治中期以降の外観を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005559"},{"id":"00005562","register_sub_id":"101","register_pk":"106550","name":"田沼家住宅外塀","kana":"たぬまけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市島田町409","lat":36.29982572,"lng":139.4436356,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造、瓦葺、総延長84m","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"09 － 0148","desc":"屋敷地の北辺，旧例幣使街道沿いに建つ。切妻造，桟瓦葺，真壁造の塀で，腰を簓子下見板張とする。北面の塀の柱間寸法は東側を１．４ｍ，西側を１．２ｍ，共に高さ２．２ｍとし，ほぼ中央で南に折れ，表門両袖塀北端部に取り付く。街道沿いの歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005562"},{"id":"00005560","register_sub_id":"101","register_pk":"106548","name":"田沼家住宅土蔵","kana":"たぬまけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県足利市島田町409","lat":36.29972546,"lng":139.4434292,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"09 － 0146","desc":"主屋の北西方に建つ桁行３間半，梁間３間の２階建土蔵で，南北棟，切妻造，桟瓦葺の置屋根を載せ，東面に庇を差し掛けて戸口を設ける。外部白漆喰塗とし，２階の東面と南面に窓を開ける。年代は内部柱の墨書による。旧例幣使街道寄りの裏庭空間を構成する要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005560"},{"id":"00001891","register_sub_id":"101","register_pk":"102881","name":"塚田家住宅板塀","kana":"つかだけじゅうたくいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町2-16","lat":36.37849854,"lng":139.73095182,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、延長113m","structure_material":"木造","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0045","desc":"塚田家の屋敷地は，かつて栃木河岸と呼ばれた巴波川の東岸沿いにある。縦板張で桟瓦葺屋根をもつ板塀は，屋敷地と巴波川を画するもので，延長約１１３ｍの間に５箇所の潜戸が設けられている。河運で栄えた商業都市の景観を伝える欠かせない要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001891"},{"id":"00001893","register_sub_id":"101","register_pk":"102883","name":"塚田家住宅旧米蔵","kana":"つかだけじゅうたくきゅうこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県栃木市倭町2-16","lat":36.37816846,"lng":139.73071466,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0047","desc":"巴波川沿いの細長い屋敷地の南西，川に面して建つ。切妻造・桟瓦葺，南北棟の土蔵で，米を収納していたため，室内高が高くなっている。外壁はもと白漆喰塗で，北の妻面は簓子下見板張とする。他に比べて規模は小さいが，豪商の屋敷構に欠かせない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001893"},{"id":"00001890","register_sub_id":"101","register_pk":"102880","name":"塚田家住宅旧主屋","kana":"つかだけじゅうたくきゅうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町2-16","lat":36.37865179,"lng":139.73119242,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積177㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0044","desc":"塚田家は弘化年間創業と伝える材木問屋。旧主屋は巴波川東岸沿いの屋敷地のほぼ中央に建つ。総２階建，寄棟造・桟瓦葺で，外壁は簓子下見板張とする。１・２階とも庭側３方に縁を廻して８畳間の２室とし，床の座敷は繊細な数寄屋風の意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001890"},{"id":"00001892","register_sub_id":"101","register_pk":"102882","name":"塚田家住宅文庫蔵","kana":"つかだけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県栃木市倭町2-16","lat":36.37874834,"lng":139.73129293,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積79㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"09 － 0046","desc":"塚田家は旧例幣使街道栃木宿の西木戸があった幸来橋の東にある。文庫蔵は幸来橋の東南，通りと川に面して建ち，小屋梁の墨書から明治３２年の上棟とわかる。切妻造・桟瓦葺，２階建で，外壁は白漆喰塗とし，出入口や窓に観音扉を備えた本格的な土蔵建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001892"},{"id":"00008644","register_sub_id":"101","register_pk":"149365","name":"野口家住宅表門","kana":"のぐちけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県小山市大字松沼字割出1234","lat":36.3560596,"lng":139.77253403,"geo_status":"db","era":"明治前期／昭和前期移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口4.7m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0198","desc":"敷地南辺の中央に位置する。切妻造桟瓦葺の薬医門、中央に両開戸をたて、東袖に潜りを開ける。本柱上に冠木を載せ、前後に男梁を5通りに架け、貫で固めた束が棟木や母屋を支持。1軒半繁垂木。素朴なつくりながら、木太く、屋敷構えに風格を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008644"},{"id":"00008642","register_sub_id":"101","register_pk":"149363","name":"野口家住宅主屋","kana":"のぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"栃木県","address":"栃木県小山市大字松沼字割出1234","lat":36.35636477,"lng":139.77263442,"geo_status":"db","era":"江戸末期／昭和前期増改築・昭和50年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積341㎡、望楼付","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0196","desc":"敷地中央に南面して建つ。桁行24ｍ梁間12ｍ、木造平屋建。緩やかに起る入母屋造桟瓦葺で、正面2ヶ所に千鳥破風を付ける。周囲に銅板葺庇をまわし、正面中央に入母屋造妻入の式台を突出する。変化に富む外観のなか、入母屋造銅板葺の展望台が一際目を引く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008642"},{"id":"00008643","register_sub_id":"101","register_pk":"149364","name":"野口家住宅南蔵","kana":"のぐちけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県小山市大字松沼字割出1234","lat":36.35599833,"lng":139.77276648,"geo_status":"db","era":"明治前期／昭和前期移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積45㎡","structure_material":"土蔵造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"09 － 0197","desc":"敷地の南東隅に西面して建つ。桁行8.3ｍ梁間4.5ｍの土蔵造平屋建、切妻造妻入桟瓦葺の置屋根。4段に積み上げた大谷石を四周にまわし、漆喰仕上げとする。西面に瓦庇をかけて切石により出入口をつくり、鉄板貼の引込戸をたてる。敷地景観を構成する一要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008643"},{"id":"00014566","register_sub_id":"101","register_pk":"515108","name":"濱田窯長屋門","kana":"はまだがまながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県芳賀郡益子町大字益子字日向3387他","lat":36.46989722,"lng":140.10795556,"geo_status":"db","era":"明治前期／昭和9年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"09 - 0271","desc":"陶芸家濱田庄司が近隣農村から移築改修した入母屋造茅葺の長屋門。門東側はトイレ付滞在室、西側は作陶室、正面は与力窓で伝統的外観。背面は扇垂木で意匠を凝らし、側面に窓を並べ開放的。滞在室は梁組を見せ、益子焼の便器を備え民芸調意匠を垣間見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014566"},{"id":"00000631","register_sub_id":"101","register_pk":"101621","name":"林家住宅","kana":"はやしけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県那須郡那須町大字湯本206","lat":37.08813333,"lng":140.01133056,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建，瓦葺，建築面積388㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0012","desc":"戦前の代表的な分譲住宅地として名高い大和郷の一画に建つ。勾配の緩やかな寄棟屋根，Ｓ字型の瓦，玄関脇の棕櫚などにスパニッシュ住宅の要素が認められる。玄関扉三方枠の装飾，居間の手斧仕上の梁，石貼りの暖炉などに見所をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000631"},{"id":"00004915","register_sub_id":"101","register_pk":"105905","name":"原田家住宅主屋","kana":"はらだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市通6-3225-1","lat":36.33798914,"lng":139.44136721,"geo_status":"db","era":"昭和17頃／昭和53曳家","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0123","desc":"店舗南面に壁を接して建つ。寄棟造桟瓦葺の木造平屋で，外壁をモルタル塗とする。北東隅の玄関に１０畳が続き，これより南に延びる廊下を挟み，東側に８畳居室と水回りが，西側に居室２室が並ぶ。南側に２室増築されたが，戦前の中廊下の形式を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004915"},{"id":"00005747","register_sub_id":"101","register_pk":"106735","name":"仏蘭西懐石ふじもと（旧ホーン家住宅ガレージ棟）","kana":"ふらんすかいせきふじもと（きゅうほーんけじゅうたくがれーじとう）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県日光市山内2339","lat":36.75681931,"lng":139.60229421,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"石造及び木造2階建、鉄板葺、建築面積50㎡","structure_material":"石造及び木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"09 － 0156","desc":"主屋の西方に位置し，南北棟で建つ。桁行９．２ｍ，梁間５．５ｍ規模，切妻造，鉄板葺の２階建で，１階ガレージは石造，２階は木造とし，２階外壁はシングル張仕上げとする。バンガロー風の外観意匠で，妻側１階入口上の庇や切妻屋根を方杖で受ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005747"},{"id":"00003186","register_sub_id":"101","register_pk":"104176","name":"松村家住宅内蔵","kana":"まつむらけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県足利市大門通2380","lat":36.335674,"lng":139.451614,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"土蔵造地上2階地下1階建、瓦葺、建築面積21㎡","structure_material":"土蔵造地上2階地下1階建","registered":"2003.03.18(平成15.03.18)","register_no":"09 － 0069","desc":"蔵前を介して主屋の西側に南北棟で建つ。桁行３間梁間２間規模，桟瓦葺，切妻造，平入の３階建土蔵で，地下室をもつ点，洗出し仕上の外装に目地を切って石造風に見せている点に特徴がある。現在は「松村記念館」の資料展示室として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003186"},{"id":"00003187","register_sub_id":"101","register_pk":"104177","name":"松村家住宅表門","kana":"まつむらけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県足利市大門通2380","lat":36.33549954,"lng":139.45177334,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造、瓦葺、間口2.4m","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"09 － 0070","desc":"主屋玄関部の東南方に位置し，屋敷地南側道路から玄関部に通じる石畳の中程に建つ。間口８尺，小平の柱を用いた１間１戸の腕木門で，桟瓦葺，切妻造の屋根を載せ，玄関側に控柱を建て，内開き板戸を付ける。足利名士の邸宅構えに欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003187"},{"id":"00003185","register_sub_id":"101","register_pk":"104175","name":"松村家住宅主屋","kana":"まつむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県足利市大門通2380","lat":36.335651,"lng":139.451706,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積207㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"09 － 0068","desc":"大門通り沿いの屋敷地のほぼ中央に南面して建つ。たちの高い，東西棟，桟瓦葺，入母屋造の木造２階建で，１階は田字型８畳４室の南・西・北三方に縁を廻し，東に台所，西に８畳の奥の間と内蔵蔵前，東南に洋室付き玄関を張出す。大工棟梁は関口忠吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003185"},{"id":"00009580","register_sub_id":"101","register_pk":"194576","name":"松本家住宅裏門・瓦小屋及び塀","kana":"まつもとけじゅうたくうらもん・かわらごやおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県下都賀郡壬生町中央町340他","lat":36.42460549,"lng":139.80329575,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"裏門 木造、瓦葺、間口2.3m 瓦小屋 木造平屋建、瓦葺、建築面積6.6㎡ 塀 木造、瓦葺、総延長30m","structure_material":"裏門 木造","registered":"2013.06.21(平成25.06.21)","register_no":"09 － 0211","desc":"裏門は敷地南東に南北棟で建ち、間口二・三メートル、一間薬医門、切妻造桟瓦葺である。門両端から東西に簓子下見板張の塀をのばし、塀の南東端には木造平屋建の瓦小屋を残す。敷地外郭を形成し、主屋などと一体として風格ある屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009580"},{"id":"00009579","register_sub_id":"101","register_pk":"194575","name":"松本家住宅表門","kana":"まつもとけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県下都賀郡壬生町中央町1319-15他","lat":36.42471108,"lng":139.80292835,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、瓦葺、間口4.9m、袖塀付","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"09 － 0210","desc":"敷地の西寄り、主屋正面に構える。間口四・九メートルの薬医門、切妻造桟瓦葺で、両側に袖塀を付属する。成の高い冠木上に三斗を置いて小屋を請ける。ケヤキの良材を用いた大型の表門で、組物間や妻飾に精緻な彫刻を飾り、袖塀とともに豪壮な構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009579"},{"id":"00009578","register_sub_id":"101","register_pk":"194574","name":"松本家住宅居住蔵","kana":"まつもとけじゅうたくきょじゅうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県下都賀郡壬生町中央町1319-15他","lat":36.42478961,"lng":139.8031544,"geo_status":"db","era":"明治40頃／平成22改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"09 － 0209","desc":"三棟並ぶ土蔵の東端に南北棟で建つ。土蔵造二階建、桁行七・三メートル梁間四・六メートル、切妻造桟瓦葺で、南妻面に入口を開く。外壁は漆喰壁で鉢巻を廻らし、二階南面に窓を穿つ。穀蔵などとともに屋敷構えを構成する土蔵で、現在は居住の用に供している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009578"},{"id":"00009577","register_sub_id":"101","register_pk":"194573","name":"松本家住宅穀蔵","kana":"まつもとけじゅうたくこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県下都賀郡壬生町中央町1319-15他","lat":36.42478723,"lng":139.80309015,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"09 － 0208","desc":"三棟並ぶ土蔵の中央に南北棟で建つ。土蔵造二階建、桁行七・三メートル梁間四・六メートル、切妻造桟瓦葺。南妻を戸口とし、二階両妻面に窓を穿つ。内部は北半を吹抜けとして穀物保管の便を図る。文庫蔵、居住蔵とともに伝統的な屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009577"},{"id":"00009575","register_sub_id":"101","register_pk":"194571","name":"松本家住宅主屋","kana":"まつもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県下都賀郡壬生町中央町340他","lat":36.42471822,"lng":139.80330669,"geo_status":"db","era":"大正元","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積142㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"09 － 0206","desc":"壬生町の中心部に所在し、日光西街道沿いの敷地に西面して建つ。木造平屋建、寄棟造桟瓦葺で、正面に入母屋屋根の玄関を構え、東西方向に座敷を配して南東面に縁を廻らす。玄関妻飾や室内の透彫欄間に、鶴などを主題とした巧緻で華やかな彫刻を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009575"},{"id":"00009576","register_sub_id":"101","register_pk":"194572","name":"松本家住宅文庫蔵","kana":"まつもとけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県下都賀郡壬生町中央町1319-16","lat":36.42478961,"lng":139.80302115,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"09 － 0207","desc":"三棟並び建つ土蔵の西端に南北棟で建つ。土蔵造二階建、桁行七・三メートル梁間四・六メートル、切妻造桟瓦葺である。西面を戸口とし、南北妻面に窓を設けて掛子塗の土戸を両開きとする。一時期銀行の書類保管庫などとして使用され、住民生活に貢献した土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009576"},{"id":"00004918","register_sub_id":"101","register_pk":"105908","name":"柳田家住宅表門","kana":"やなぎだけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県足利市通6-3226-1他","lat":36.3381841,"lng":139.44112573,"geo_status":"db","era":"大正初期／昭和53曳家","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造、瓦葺、間口3.2m","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"09 － 0126","desc":"事務所と倉庫の間に建つ長屋門形式の門。切妻造桟瓦葺。１間規模の門口を挟み，東側半間は正面に張出し，敷地内事務所入口の目隠とする。西側二間半は倉庫の蔵前を兼ね，格子付窓が付く。漆喰塗と下見板張の外壁は両脇の建物と調和し，連続した景観を作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004918"},{"id":"00000752","register_sub_id":"101","register_pk":"101742","name":"横山郷土館離れ","kana":"よこやまきょうどかんはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県栃木市入舟町2-16","lat":36.38134437,"lng":139.73205053,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建，鋼板葺，建築面積31㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"09 － 0010","desc":"店舗及び住宅の後方，屋敷地の西方に建つ。外観はハーフティンバー形式を用いて洋風でまとめる。内部は和風を基調とするが天井を洋風につくるなど和洋折衷の意匠になる。小規模ながら完成度の高い洋風建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000752"},{"id":"00005742","register_sub_id":"101","register_pk":"106730","name":"レストラン明治の館（旧ホーン家住宅主屋）","kana":"れすとらんめいじのやかた（きゅうほーんけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県日光市山内2339","lat":36.75679483,"lng":139.60297155,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"石造地上3階地下1階建、鉄板葺、建築面積261㎡","structure_material":"石造地上3階地下1階建","registered":"2006.10.18(平成18.10.18)","register_no":"09 － 0154","desc":"南面にヴェランダ玄関を配し，両妻壁に煖炉煙突を立ち上げた切妻造，鉄板葺の石造２階建の別荘建築で，地階及び屋階を設け，東面に石造２階建の付属舎を突き出す。地元稲荷川の安山岩を用い，乱積風に見せた精緻な石積技法が野趣に富んだ外観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005742"},{"id":"00005746","register_sub_id":"101","register_pk":"106734","name":"レストラン明治の館別館游晏山房（旧ホーン家住宅別棟）","kana":"れすとらんめいじのやかたべっかんゆうあんさんぼう（きゅうほーんけじゅうたくべっとう）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県日光市山内2339","lat":36.75696128,"lng":139.60309442,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"石造平屋建、鉄板葺、建築面積56㎡","structure_material":"石造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"09 － 0155","desc":"主屋付属舎の北方に南北棟で建つ。桁行１２ｍ，梁間４．５ｍの規模，切妻造，鉄板葺の石造平屋建で，外周壁には稲荷川の安山岩を整層に，妻面まで積む。もとメイド部屋で，レストランとして活用している。主屋付属舎とは石造の旧ボイラー室・通路等で繋ぐ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005746"},{"id":"00002015","register_sub_id":"101","register_pk":"103005","name":"石坂家住宅主屋","kana":"いしざかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県渋川市下ノ町2467-1","lat":36.49585224,"lng":139.00363662,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造3階建、瓦葺、建築面積229㎡","structure_material":"木造3階建","registered":"2000.12.04(平成12.12.04)","register_no":"10 － 0057","desc":"江戸時代初頭以来当地に居住し，代々七左衛門を襲名する名家の住宅主屋。主要地方道渋川松井田線に南面する敷地に在るが，区画整理のため新築店舗の背後の現在地に曳屋されている。入母屋造の豪壮な造りで，数少ない渋川市内の３階建和風住宅として知られる","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002015"},{"id":"00015280","register_sub_id":"101","register_pk":"532404","name":"江原本家奥庫（旧朝日町奥庫）","kana":"えばらほんけおくぐら（きゅうあさひちょうおくぐら）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県前橋市富士見町赤城山字竜ノ口1825-47他","lat":36.48991111,"lng":139.11639444,"geo_status":"db","era":"明治10年／平成13年移築・令和6年改修","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0354","desc":"前橋市朝日町から移築した旧家財蔵。敷地南東に北面して建つ2階建切妻造平入桟瓦葺。外壁白漆喰塗仕上で水切二段、腰は黒漆喰塗仕上。内部１階は腰に中敷居を入れ、小屋は地棟に束が立ち並ぶなど特徴的。戸口に掛子塗扉を吊り窓に鉄格子を嵌めた厳重な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015280"},{"id":"00015281","register_sub_id":"101","register_pk":"532405","name":"江原本家質庫（旧朝日町質庫）","kana":"えばらほんけしちぐら（きゅうあさひちょうしちぐら）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県前橋市富士見町赤城山字竜ノ口1825-47他","lat":36.48999444,"lng":139.116225,"geo_status":"db","era":"明治前期／平成13年移築・令和6年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0355","desc":"前橋市朝日町から移築した旧質庫。敷地南方に北面して建つ2階建寄棟造平入桟瓦葺。外壁白漆喰塗仕上で水切二段、腰は黒漆喰塗仕上。内部１階は腰に中敷居を入れ、二重梁の和小屋は地棟に束が立ち並ぶなど特徴的。窓少なく閉鎖的で掛子塗扉など丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015281"},{"id":"00015279","register_sub_id":"101","register_pk":"532403","name":"江原本家清芳山荘（旧木村清四郎邸）","kana":"えばらほんけせいほうさんそう（きゅうきむらせいしろうてい）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県前橋市富士見町赤城山字竜ノ口1825-39他","lat":36.49034167,"lng":139.11650278,"geo_status":"db","era":"大正2年／昭和11年・同60年移築","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積188㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"10 - 0353","desc":"赤城山の南麓に移築した住宅の主屋。木造平屋建で、西の玄関から東の続き間座敷へ至り、南西に洋室を配す。座敷は床・床脇・付書院を備えて良材を用い、洋室は木製マントルピースを備え、天井や窓建具は井桁と菱を組合せた意匠で飾った上質な近代和風の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015279"},{"id":"00004942","register_sub_id":"101","register_pk":"105932","name":"小川家住宅主屋","kana":"おがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県太田市安養寺町93-1","lat":36.26028562,"lng":139.30764303,"geo_status":"db","era":"江戸後期／昭和5改造","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階一部平屋建、瓦葺、建築面積301㎡","structure_material":"木造2階一部平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0145","desc":"広大な敷地中央に南面して建つ。中央より東側，切妻造２階建の主体部が古く，西側の寄棟造平屋建は後世の改造になる。東側を独立柱がある広い土間，西側を６間取の床上部とした平面構成で，主体部の軸組や小屋組はよく残り，１８世紀末頃の形式を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004942"},{"id":"00004943","register_sub_id":"101","register_pk":"105933","name":"小川家住宅長屋門","kana":"おがわけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県太田市安養寺町93-1","lat":36.2599878,"lng":139.30770807,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積176㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"10 － 0146","desc":"東西棟の切妻造平屋建，桟瓦葺で，桁行２６ｍの規模をもつ。中央に中２階を設けた門口を構え，東に土間で１室の倉庫，西には南面玄関付の２つの住戸を配し，その間には南北に抜ける通路を設ける。敷地南にあり，豪壮な屋敷に相応しい構えをかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004943"},{"id":"00003819","register_sub_id":"101","register_pk":"104809","name":"片山家住宅井戸屋","kana":"かたやまけじゅうたくいどや","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県太田市新田溜池町128-1","lat":36.3268395,"lng":139.27448788,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積3.9㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0117","desc":"長屋門門口から主屋土間入口へ至る通路の中程東方に位置し，藪塚石の基壇上に南北棟で建つ。規模は桁行１間１尺梁間１間ほどで，切妻屋根に桟瓦を葺く。井戸側は藪塚石を円筒状に積み上げ，上部は花崗石を井桁に組む。上層農家の屋敷構えを知るうえで貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003819"},{"id":"00003816","register_sub_id":"101","register_pk":"104806","name":"片山家住宅北の蔵","kana":"かたやまけじゅうたくきたのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県太田市新田溜池町128-1","lat":36.32713072,"lng":139.274216,"geo_status":"db","era":"明治18頃","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0114","desc":"屋敷地北西端に位置し，東西棟で建つ。桁行４間梁間２間半，平入の２階建土蔵で，屋根は切妻造，桟瓦葺の置屋根とする。道具蔵として建てられ，南面東半に間口２間奥行半間の土庇を架けて蔵前をとり，戸口や窓には漆喰塗の観音扉を建て込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003816"},{"id":"00003818","register_sub_id":"101","register_pk":"104808","name":"片山家住宅下の便所","kana":"かたやまけじゅうたくしたのべんじょ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"群馬県","address":"群馬県太田市新田溜池町128-1","lat":36.32693484,"lng":139.27457183,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造平屋建、瓦葺、建築面積4.4㎡","structure_material":"土蔵造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0116","desc":"主屋の東方に西面して建つ。桁行２間梁間半間，南北棟，切妻造，桟瓦葺，平入の木造平屋建で，藪塚石を基礎とした土台建ちの真壁造とする。半畳規模の室を４室南北に並べ，中央２室を大便所とする。上層農家の屋敷構えを構成する要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003818"},{"id":"00003814","register_sub_id":"101","register_pk":"104804","name":"片山家住宅主屋","kana":"かたやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県太田市新田溜池町128-1","lat":36.32695342,"lng":139.27431077,"geo_status":"db","era":"明治6頃","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺、建築面積304㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0112","desc":"屋敷地のほぼ中央に南面して建つ。主体部は桁行１０間半梁間４間規模の切妻造２階建で，南面と西面に１間幅，北面に２間幅の下屋を廻す。東側を下手とし，正面に式台玄関を設け，屋根中央に桁行６間梁間１間のケブダシを上げる。上層養蚕農家の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003814"},{"id":"00003815","register_sub_id":"101","register_pk":"104805","name":"片山家住宅長屋門","kana":"かたやまけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県太田市新田溜池町128-1","lat":36.326694,"lng":139.274353,"geo_status":"db","era":"明治6頃","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積109㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0113","desc":"屋敷地南辺の中央に建つ。桁行１０間梁間３間，切妻造，桟瓦葺，平入で，２カ所の門口を設け，東端に物置，門口間にカイコヤを配し，西端門口は通常閉切りとする。外観は腰押縁下見張，上部真壁造とし，軒を出桁に造る。主屋玄関に対応した門口の構成に特色。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003815"},{"id":"00003817","register_sub_id":"101","register_pk":"104807","name":"片山家住宅南の蔵","kana":"かたやまけじゅうたくみなみのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県太田市新田溜池町128-1","lat":36.32706002,"lng":139.274185,"geo_status":"db","era":"明治18頃","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0115","desc":"主屋の西北方，北蔵の南方に南北棟で建つ。桁行２間半梁間２間，平入の２階建土蔵で，屋根は北蔵同様の置屋根とする。衣裳蔵として建てられ，東面中央に間口２間奥行半間の下屋を付け，南妻面２階に窓を開ける。北蔵とともに主屋裏庭空間の構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003817"},{"id":"00007454","register_sub_id":"101","register_pk":"108436","name":"割烹旅館ときわ荘土蔵（旧櫛渕家住宅土蔵）","kana":"かっぽうりょかんときわそうどぞう（きゅうくしぶちけじゅうたくどぞう）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県富岡市富岡字蛾成地1729-1","lat":36.26007923,"lng":138.89512145,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"10 － 0267","desc":"主屋北面の西端に接して建つ。桁行７．３ｍ梁間４．４ｍ規模の土蔵造２階建で、南北棟の切妻造妻入桟瓦葺とする。南面１階が主屋廊下に面し、黒漆喰の磨仕上げとし、楣は虹梁風に造り、絵様を飾る。外壁も黒漆喰で、高く下見板を張り、窓には銅板葺庇を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007454"},{"id":"00007455","register_sub_id":"101","register_pk":"108437","name":"割烹旅館ときわ荘長屋門（旧櫛渕家住宅長屋門）","kana":"かっぽうりょかんときわそうながやもん（きゅうくしぶちけじゅうたくながやもん）","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県富岡市富岡字蛾成地1729-1","lat":36.26023777,"lng":138.89514689,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積61㎡、塀付","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"10 － 0268","desc":"敷地の北辺、道路沿いに位置する。桁行２０ｍ梁間２．８ｍの東西に長い木造平屋建で、東面には延長１７ｍの屋根塀が続く。屋根は桟瓦葺で西寄棟造、東端に直交する棟や落棟を設ける。土台は擬石仕上げで、漆喰壁腰下見板張とし、伝統的な街路景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007455"},{"id":"00007453","register_sub_id":"101","register_pk":"108435","name":"割烹旅館ときわ荘本館（旧櫛渕家住宅主屋）","kana":"かっぽうりょかんときわそうほんかん（きゅうくしぶちけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県富岡市富岡字蛾成地1729-1","lat":36.26008811,"lng":138.89522931,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積278㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"10 － 0266","desc":"通りに北面する敷地のほぼ中央に建つ。東西棟の寄棟造平屋建３棟を雁行型に配し、桁行３３ｍに及ぶ。北面には千鳥破風を設け、入母屋造の玄関を構える。屋根は軒先を銅板葺とする桟瓦葺。随所に銘木が使われ、細部意匠にまで凝った質の高い近代和風住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007453"},{"id":"00013685","register_sub_id":"101","register_pk":"505195","name":"金井義明家住宅主屋","kana":"かないよしあきらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県伊勢崎市境島村字新野2439他","lat":36.24531667,"lng":139.243725,"geo_status":"db","era":"明治元年／明治17年・平成16年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造2階建、瓦葺、建築面積168㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"10 － 347","desc":"木造二階建桟瓦葺で越屋根を二箇所掲げる養蚕、蚕種製造民家。正背面と東側面に下屋を設ける。二階は旧蚕室で正面に手摺付の縁を備える。縁の張出し等は建築後の改修とみられ、島村における中規模の蚕種製造民家の成立と、その後の変遷を示す遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013685"},{"id":"00002126","register_sub_id":"101","register_pk":"103116","name":"川端家住宅井戸屋形","kana":"かわばたけじゅうたくいどやかた","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.28212517,"lng":139.09979296,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積9.9㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0071","desc":"主屋の西側，湯殿の背面に連続して建っている。南北棟で切妻造・桟瓦葺，四方吹放しの建物で，中央部に井戸があり，四周は玉石を廻して段差をつくる。簡素な形式であるが，大規模な屋敷の水廻りの施設であり，生活空間の構成上欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002126"},{"id":"00002127","register_sub_id":"101","register_pk":"103117","name":"川端家住宅稲荷社","kana":"かわばたけじゅうたくいなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.28217529,"lng":139.09973587,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積1.9㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0072","desc":"屋敷地の西南隅にある屋敷神。切石積基壇の上に建つ総欅造の１間社流造社殿で，屋根は銅板葺。向拝は角柱で３斗を組み，身舎は丸柱に絵様肘木とする。２軒繁垂木の軒，３面の擬宝珠高欄付の縁及び浜床など，小規模ながら正統的なつくりとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002127"},{"id":"00002118","register_sub_id":"101","register_pk":"103108","name":"川端家住宅大門","kana":"かわばたけじゅうたくおおもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.28190416,"lng":139.10012962,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"薬医門、瓦葺、間口2.8m","structure_material":"薬医門","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0063","desc":"屋敷の正門で，敷地東面，東穀蔵と番頭部屋の間に建つ。両側に袖塀を設けた１間１戸薬医門で，切妻造・桟瓦葺，軒は２軒繁垂木，外側を鏡天井，内側を格天井とする。総欅造で，保存状態も良好であり，年代は別荘と同時期の建設と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002118"},{"id":"00002116","register_sub_id":"101","register_pk":"103106","name":"川端家住宅奥蔵","kana":"かわばたけじゅうたくおくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.28218004,"lng":139.09979623,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0061","desc":"屋敷地の南西隅に建つ。南北棟の切妻造・桟瓦葺，２階建の重厚な土蔵である。主屋側の東面に蔵前の庇を設け，奥に観音扉の入口とする。両妻面に観音扉の２階窓をつくり，軒先に蛇腹を廻すなど，全体に丁寧な仕事が伺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002116"},{"id":"00002124","register_sub_id":"101","register_pk":"103114","name":"川端家住宅木小屋","kana":"かわばたけじゅうたくきごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.282314,"lng":139.100037,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0069","desc":"屋敷西面のほぼ中央，質蔵の北側に建つ。南北棟で切妻造・桟瓦葺きの細長い建物で，東面を吹放し，他を土壁とする。屋敷内で適宜間伐した樹木を保管しておくための建物。内向きの付属的な建物であるが，豪農の屋敷の構成要素として欠かせない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002124"},{"id":"00002117","register_sub_id":"101","register_pk":"103107","name":"川端家住宅質蔵","kana":"かわばたけじゅうたくしちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県藤岡市立石新田391","lat":36.28224805,"lng":139.09994209,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"10 － 0062","desc":"屋敷地西側，奥蔵の背後に並んで建つ。南北棟の切妻造・桟瓦葺，２階建の土蔵である。両妻面には観音扉窓を上下に設けるが，軒先は簡素に扱う。東面の庇は，南端が扉口への出入部となり，残りを畳敷の前座敷にするなど，質蔵としての性格があらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002117"}];
